function lecture(id, skillId, objectives, sections, workedExamples, misconceptions, checks) { return { id, skillId, objectives, sections, workedExamples, misconceptions, checks, assets: [] }; }
function question(id, skillId, difficulty, stem, options, answerIndex, reasons, reviews) { return { id, skillId, stem, options, answerIndex, reasons, difficulty, cognitiveProcess: ["排泄與恆定判讀", "證據推理"], representationType: "文字與資料判讀", misconceptionTargets: [], reviews, assets: [] }; }
function stimulus(id, skillId, type, content, accessibility, questions) { return { id, skillId, type, content, accessibility, questions, assets: [] }; }

const lectures = [];
const questions = [];
const stimuli = [];

lectures.push(lecture("BIO_R4_L_S073", "BIO_R4_S073",
  ["依物質來源區分排泄與排遺", "由生活情境判斷二氧化碳、尿素與未消化殘餘物的排出類型"],
  [
    { id: "BIO_R4_L_S073_SEC_01", title: "排泄移除代謝廢物", content: "細胞進行代謝會產生二氧化碳、含氮廢物與多餘水分等。身體將這些物質移出體外屬於排泄，可由肺、腎臟與皮膚等器官參與。" },
    { id: "BIO_R4_L_S073_SEC_02", title: "排遺排出食物殘餘", content: "食物中未被消化或吸收的成分留在消化道內，經大腸形成糞便並由肛門排出，稱為排遺。這些殘餘物沒有先成為細胞代謝產物。" },
    { id: "BIO_R4_L_S073_SEC_03", title: "出口不能單獨分類", content: "分類關鍵是物質來源，不只是從哪個開口離開。糞便含未消化殘餘屬排遺；呼出的二氧化碳來自細胞代謝，即使由呼吸道離開仍屬排泄。" },
    { id: "BIO_R4_L_S073_SEC_04", title: "同一情境可能並存", content: "人體每天可能同時排尿、呼氣、流汗與排便，其中前三者可包含代謝廢物排出，排便則主要是排遺。不能把身體所有排出現象都用同一名詞概括。" },
  ],
  [
    { id: "BIO_R4_L_S073_EX_01", prompt: "細胞呼吸產生的二氧化碳由肺排出，屬於何者？", steps: ["追蹤二氧化碳是否由細胞代謝產生", "再判斷移出體外的類型"], answer: "排泄", why: "二氧化碳是細胞呼吸的代謝產物，經血液送到肺部後排出；分類依物質來源，因此即使出口是呼吸道，仍屬排泄。" },
    { id: "BIO_R4_L_S073_EX_02", prompt: "纖維未被消化而隨糞便排出，屬於何者？", steps: ["確認纖維仍在消化道內", "檢查是否曾成為細胞代謝廢物"], answer: "排遺", why: "未消化纖維沒有先被吸收進入細胞，也不是細胞代謝產物；它只是消化道內容物的殘餘，因此排出屬於排遺。" },
    { id: "BIO_R4_L_S073_EX_03", prompt: "只看物質從肛門排出，能否判定是排泄？", steps: ["區分出口與來源兩種判準", "追查排出物是否來自細胞代謝"], answer: "不能，應先判斷物質來源", why: "出口位置無法取代來源證據；糞便主要是未消化食物殘餘與消化道成分，沒有先成為細胞代謝廢物，所以主要屬排遺。" },
  ],
  [
    { belief: "身體排出任何物質都叫排泄", whyWrong: "未消化食物殘餘排出屬排遺，和細胞代謝廢物不同。", correction: "先追查物質來源，代謝廢物移除稱排泄，消化道殘餘排出稱排遺。" },
    { belief: "排便是腎臟排泄的一部分", whyWrong: "糞便主要在大腸形成並由肛門排出，不是腎臟製造的尿液。", correction: "腎臟參與尿液形成與排泄，排便則是消化道完成的排遺。" },
    { belief: "呼出的二氧化碳不是排泄，因為沒有經過腎臟", whyWrong: "排泄器官不只腎臟，肺也能排出細胞代謝產生的二氧化碳。", correction: "凡移除代謝廢物可屬排泄，應依物質來源而非是否經腎臟判斷。" },
    { belief: "未吸收的食物會先進入細胞再成為糞便", whyWrong: "未吸收成分一直留在消化道管腔，沒有先進入體內細胞。", correction: "糞便主要由未消化殘餘與消化道成分構成，排出過程屬排遺。" },
  ],
  [
    { prompt: "排泄與排遺最重要的分類依據是什麼？", answer: "排出物是否來自細胞代謝", reason: "代謝廢物移除屬排泄，未消化食物殘餘離開消化道則屬排遺。" },
    { prompt: "尿素隨尿液排出為何屬排泄？", answer: "尿素是蛋白質代謝後形成的含氮廢物", reason: "它由體內代謝產生並經血液送到腎臟，最後隨尿液移出體外。" },
    { prompt: "糞便排出為何主要屬排遺？", answer: "其中主要含未消化與未吸收的殘餘物", reason: "這些成分留在消化道管腔，並沒有先成為細胞的代謝廢物。" },
  ],
));

questions.push(
  question("BIO_R4_Q_073_01", "BIO_R4_S073", "foundation", "細胞代謝產生的廢物被移出體外，稱為何者？", ["排泄", "排遺", "消化", "吸收"], 0, ["排泄是身體移除細胞代謝廢物的過程，符合題幹來源。", "排遺主要排出未消化食物殘餘，不是細胞代謝廢物。", "消化將大分子食物分解，並非把代謝廢物移出體外。", "吸收讓小分子進入體內，方向與廢物排出正好不同。"], ["題幹明示物質來自細胞代謝，直接對應排泄的定義。", "分類時先看來源，再看器官，能避免把排泄與排遺混為一談。"]),
  question("BIO_R4_Q_073_02", "BIO_R4_S073", "foundation", "未消化食物殘餘隨糞便排出，主要稱為何者？", ["細胞呼吸", "排遺", "氣體交換", "血液循環"], 1, ["細胞呼吸發生在細胞內，利用養分釋能而不是形成糞便。", "未消化殘餘由消化道排出，符合排遺的物質來源與路徑。", "氣體交換是氧與二氧化碳跨膜，不是糞便排出。", "血液循環運送物質，糞便則位於消化道管腔內形成。"], ["未消化代表成分沒有被吸收進細胞，因此不是代謝後的排泄物。", "大腸形成糞便並由肛門排出，是排遺而非腎臟排泄。"]),
  question("BIO_R4_Q_073_03", "BIO_R4_S073", "foundation", "呼出的二氧化碳主要屬於哪種排出？", ["排遺", "吞嚥", "排泄", "吸收"], 2, ["二氧化碳不是未消化食物殘餘，因此不屬排遺。", "吞嚥把食團送入食道，方向與二氧化碳排出無關。", "二氧化碳由細胞呼吸產生，經肺移出體外屬排泄。", "吸收是物質進入體內，不能描述呼氣將廢物移出。"], ["不要把排泄限縮為排尿；肺排出代謝二氧化碳也屬排泄。", "關鍵證據是二氧化碳來自細胞代謝，而不是它從哪個開口離開。"]),
  question("BIO_R4_Q_073_04", "BIO_R4_S073", "standard", "下列哪組排出物與生理過程的配對正確？", ["糞便－細胞代謝廢物排泄", "呼氣－未消化食物排遺", "尿素－食物未吸收殘餘", "尿素隨尿排出－排泄"], 3, ["糞便主要是消化道殘餘，不能概括為細胞代謝廢物。", "呼氣排出二氧化碳，並不排出消化道內未消化食物。", "尿素由含氮物質代謝形成，不是食物留在腸道的殘餘。", "尿素是代謝廢物，經腎臟形成尿液後排出屬排泄。"], ["逐一追查物質來源，只有尿素來自代謝且被移出體外的配對正確。", "糞便與呼氣都有排出現象，但分類仍由內容物來源決定。"]),
  question("BIO_R4_Q_073_05", "BIO_R4_S073", "standard", "為何排便不宜稱為細胞代謝廢物的排泄？", ["糞便主要成分未先進入細胞代謝", "糞便一定完全沒有水", "大腸不屬人體器官", "排便時身體沒有活動"], 0, ["多數糞便成分留在消化道內，未先成為細胞代謝產物。", "糞便含有水分，且水分有無不是排泄與排遺的唯一判準。", "大腸是人體消化器官，不能以否認器官身分解釋分類。", "排便需要肌肉與神經活動，不能說身體在此時完全沒有活動。"], ["排遺的核心是未消化或未吸收殘餘，與是否含水或是否活動無關。", "消化道管腔可視為與外界相通，未吸收物沒有真正進入內部細胞。"]),
  question("BIO_R4_Q_073_06", "BIO_R4_S073", "standard", "汗液中的部分水與鹽離開身體，最接近哪項過程？", ["排遺", "排泄", "咀嚼", "受精"], 1, ["汗液不是未消化食物殘餘，因此不能歸為消化道排遺。", "皮膚可排出水與少量鹽，屬身體排泄與調節的一部分。", "咀嚼只在口腔切碎食物，不會形成汗液。", "受精是生殖細胞結合，與皮膚排出汗液沒有關聯。"], ["皮膚也是排泄相關器官，但汗液主要意義還包括體溫調節。", "同一生理現象可有多項功能，排出物來源仍支持其包含排泄作用。"]),
  question("BIO_R4_Q_073_07", "BIO_R4_S073", "standard", "判斷某排出物屬排泄或排遺，最先應問什麼？", ["出口名稱有幾個字", "排出時聲音大小", "物質是否由細胞代謝產生", "容器是什麼顏色"], 2, ["名稱字數是文字特徵，無法判斷排出物生理來源。", "聲音大小與物質是否經細胞代謝沒有因果關係。", "來源若為細胞代謝廢物則屬排泄，否則需再判斷是否為食物殘餘。", "容器顏色不會改變排出物形成的生理過程。"], ["以來源作第一個判準，比只記出口位置更能處理不同器官的排出。", "確認是否為代謝產物後，再追蹤肺、腎或皮膚等排出途徑。"]),
  question("BIO_R4_Q_073_08", "BIO_R4_S073", "advanced", "某物質一直留在腸腔，未被吸收便排出，最合理分類為何？", ["一定是腎臟排泄", "一定是細胞呼吸", "一定是肺部換氣", "屬排遺，因未成為細胞代謝產物"], 3, ["物質未進入血液，不會先由腎臟過濾形成尿液。", "細胞呼吸需發生在細胞內，而該物質一直留在腸腔。", "肺部換氣處理空氣進出，與腸腔殘餘排出不同。", "未吸收成分直接隨消化道殘餘離開，符合排遺。"], ["題幹特別指出未被吸收，表示物質沒有進入細胞代謝流程。", "不能因物質離開身體就一律稱排泄，仍須區分消化道排遺。"]),
  question("BIO_R4_Q_073_09", "BIO_R4_S073", "advanced", "含氮物質在細胞代謝後形成尿素，再由腎臟排出，哪段決定其屬排泄？", ["尿素來自體內代謝", "尿液容器有刻度", "排尿時經過廁所", "尿素名稱有兩個字"], 0, ["尿素由體內代謝形成，是判定其為代謝廢物排泄的關鍵。", "容器刻度只協助量體積，不會改變尿素來源。", "排尿場所是生活情境，不能決定生理分類。", "名稱字數與物質形成途徑及排出功能沒有關係。"], ["物質來源提供因果判準，器材、場所與名稱都只是外部資訊。", "尿素經血液送至腎臟並排出，完整路徑也符合排泄定義。"]),
  question("BIO_R4_Q_073_10", "BIO_R4_S073", "advanced", "某動物同時排便與排出含尿素液體，最合理敘述為何？", ["兩者都只能稱排遺", "前者主要排遺，後者屬排泄", "前者排泄，後者只屬消化", "兩者都不是排出現象"], 1, ["含尿素液體移除代謝廢物，不能和糞便一起只稱排遺。", "糞便主要含消化殘餘，尿素液體則移除代謝廢物，分類不同。", "排便不以細胞代謝廢物為主，含尿素液體也不是消化作用。", "兩者都有物質離開身體，不能說都不是排出現象。"], ["同一時間可並存排遺與排泄，不能因都離開身體就用同一名稱。", "分別追查糞便內容與尿素來源，可得到兩種不同且相容的分類。"]),
  question("BIO_R4_Q_073_11", "BIO_R4_S073", "transfer", "工廠把製程廢氣排出與把未拆封原料退回，類比人體何者最合理？", ["兩者都像排泄", "兩者都像排遺", "廢氣像排泄，退回未使用原料像排遺", "廢氣像吸收，退料像細胞呼吸"], 2, ["未使用原料沒有經製程產生，和代謝廢物來源不同。", "製程廢氣是加工產物，不能和未使用原料一起只視為殘餘退回。", "廢氣來自製程像代謝廢物，未使用原料像未消化殘餘。", "排出廢氣不是物質進入，退料也不是細胞內釋能反應。"], ["類比重點是物質有沒有進入製程，對應是否經過細胞代謝。", "模型只能幫助區分來源，不能代表人體器官結構與工廠設備完全相同。"]),
  question("BIO_R4_Q_073_12", "BIO_R4_S073", "transfer", "新物種由體表排出代謝產生的氨，應如何分類？", ["因不經腎臟所以不是排泄", "因由體表所以必是排遺", "因是氣味物質所以屬消化", "屬排泄，因氨是代謝廢物"], 3, ["排泄不限定必須經腎臟，其他構造也可能移除代謝廢物。", "出口在體表不會把代謝產物改成未消化食物殘餘。", "氣味不能決定生理來源，氨也不是食物分解的消化過程。", "氨由代謝產生並離開身體，符合排泄的核心定義。"], ["面對不同物種仍使用來源判準，就不會被器官差異誤導。", "人體常把含氮廢物轉成尿素，但其他動物直接排氨仍可屬排泄。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S073", "BIO_R4_S073", "waste-origin-table",
  { title: "四種排出物的來源紀錄", text: "學生整理四種人體排出物的主要來源。表中只描述用於本次分類的成分，不代表各排出物只含一種物質。", note: "分類時以物質是否由細胞代謝形成，或是否為未消化食物殘餘為主要依據。" },
  { summary: "表格顯示二氧化碳與尿素來自細胞代謝，未消化纖維留在腸腔，汗水含多餘水鹽。", colorIndependent: true, dataFallback: { columns: ["排出物", "主要來源"], rows: [["呼出二氧化碳", "細胞呼吸產生"], ["尿中尿素", "含氮物質代謝後形成"], ["糞便中未消化纖維", "留在消化道未吸收"], ["汗中部分水與鹽", "體內多餘成分"]] } },
  [
    question("BIO_R4_SQ_073_01", "BIO_R4_S073", "standard", "依表中來源資料，哪項最明確屬於排遺？", ["糞便中未消化纖維", "呼出二氧化碳", "尿中尿素", "汗中部分水鹽"], 0, ["未消化纖維一直留在腸腔，隨糞便排出屬排遺。", "二氧化碳由細胞呼吸產生，經肺排出屬排泄。", "尿素由含氮物質代謝形成，隨尿排出屬排泄。", "多餘水鹽經皮膚排出，具有排泄與調節意義。"], ["只有未消化纖維明示未吸收且留在消化道，符合排遺。", "呼出的二氧化碳、尿中的尿素與汗中的多餘水鹽，都曾位於體內並經排泄器官移除。"]),
    question("BIO_R4_SQ_073_02", "BIO_R4_S073", "advanced", "二氧化碳與尿素共同屬排泄的主要理由為何？", ["兩者都從同一器官排出", "兩者皆由體內代謝形成", "兩者都留在腸腔", "兩者都屬完整食物"], 1, ["二氧化碳經肺、尿素經腎臟，排出器官並不相同。", "兩者都是細胞或體內代謝後產生，移除時符合排泄。", "它們會經血液運送，不是一直留在消化道管腔。", "二氧化碳與尿素是小分子廢物，不是完整食物。"], ["不同器官可以共同參與排泄，分類依代謝來源而非器官相同。", "此比較也說明排泄系統概念不能只等同泌尿系統。"]),
    question("BIO_R4_SQ_073_03", "BIO_R4_S073", "transfer", "若發現糞便中另含少量由腸細胞脫落的物質，最合理敘述為何？", ["整份糞便立刻只算排泄", "未消化纖維改成尿素", "排出物可含多種來源，主要分類仍須說明成分來源", "排遺與排泄從此沒有差別"], 2, ["少量細胞成分不會讓未消化殘餘的主要來源憑空消失。", "纖維不會因混有細胞成分就化學轉變成含氮尿素。", "混合物可含不同來源，精確判讀應分別追查各成分。", "兩概念仍可依是否經細胞代謝區分，並非完全失去差別。"], ["真實排出物常是混合物，因此結論需指出討論的是哪一成分。", "避免用單一標籤掩蓋來源差異，是把概念應用到真實資料的關鍵。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S074", "BIO_R4_S074",
  ["比較腎臟、皮膚與肺排出物質的種類與主要功能", "依器官受損情境推論哪種代謝廢物較難移除"],
  [
    { id: "BIO_R4_L_S074_SEC_01", title: "腎臟形成尿液", content: "腎臟接收血液，將尿素、多餘水分與部分鹽類形成尿液排出，同時保留身體仍需的許多物質。腎臟是含氮廢物排泄與水鹽調節的重要器官。" },
    { id: "BIO_R4_L_S074_SEC_02", title: "皮膚形成汗液", content: "汗腺分泌汗液，含水與少量鹽類等。汗液蒸發能帶走熱量，因此流汗的主要情境常和體溫調節有關，也具有排出少量物質的作用。" },
    { id: "BIO_R4_L_S074_SEC_03", title: "肺排出氣體廢物", content: "細胞產生的二氧化碳由血液運到肺部，跨入肺泡後隨呼氣排出；呼出氣也含水氣。肺不只讓空氣進出，還是移除二氧化碳的重要排泄器官。" },
    { id: "BIO_R4_L_S074_SEC_04", title: "器官分工不可任意替代", content: "肺、腎臟與皮膚排出物有部分重疊，例如水，但主要廢物與調節角色不同。大量流汗不能完全替代腎臟排尿，腎臟也不能取代肺快速排出二氧化碳。" },
  ],
  [
    { id: "BIO_R4_L_S074_EX_01", prompt: "血中尿素升高且尿素排出下降，應優先檢查哪個器官？", steps: ["辨認尿素主要由尿液排出", "連結尿液形成器官"], answer: "腎臟", why: "尿素是含氮代謝廢物，主要由血液送至腎臟並隨尿液排出；當血中累積且尿中排出下降時，腎臟處理功能是合理優先檢查環節。" },
    { id: "BIO_R4_L_S074_EX_02", prompt: "運動時汗量增加，最直接有助哪項調節？", steps: ["確認汗液到達皮膚表面", "判斷蒸發時的熱量變化"], answer: "汗液蒸發帶走熱量，協助降溫", why: "水分由液態變成氣態需要吸收熱量，汗液在皮膚表面蒸發可帶走身體熱量；若環境濕度高而難蒸發，降溫效果會下降。" },
    { id: "BIO_R4_L_S074_EX_03", prompt: "肺換氣停止時，哪種代謝廢物最直接難以排出？", steps: ["找出由肺主要排出的物質", "區分尿素與二氧化碳途徑"], answer: "二氧化碳", why: "細胞呼吸產生的二氧化碳經血液運到肺，必須進入肺泡並隨呼氣排出；腎臟無法在短時間內取代肺的氣體交換與排出功能。" },
  ],
  [
    { belief: "只有腎臟參與排泄", whyWrong: "肺排出二氧化碳，皮膚也可排出汗液中的水與鹽。", correction: "排泄涉及多個器官，應依代謝廢物種類判斷主要排出途徑。" },
    { belief: "流汗可完全取代排尿", whyWrong: "汗液與尿液成分及調節方式不同，尿素主要仍由腎臟排出。", correction: "皮膚與腎臟可都排水鹽，但腎臟對含氮廢物及水鹽調節不可被完全取代。" },
    { belief: "肺只吸入氧氣，不參與排泄", whyWrong: "肺會把細胞代謝產生的二氧化碳由血液移到肺泡並排出。", correction: "肺同時參與氣體交換與二氧化碳排泄，呼出氣也帶走部分水氣。" },
    { belief: "汗液只要分泌就一定能有效降溫", whyWrong: "主要降溫來自蒸發，若汗液滴落或環境濕度高，效果會降低。", correction: "判斷散熱需看汗液是否蒸發，不能只用分泌量代表實際帶走熱量。" },
  ],
  [
    { prompt: "尿素主要由哪個器官排出？", answer: "腎臟", reason: "腎臟從血液處理含氮廢物，尿素隨形成的尿液離開身體。" },
    { prompt: "汗液蒸發如何協助體溫調節？", answer: "蒸發吸熱並帶走體表熱量", reason: "汗水由液態變氣態需要能量，因此可降低皮膚及流經皮膚血液的熱量。" },
    { prompt: "肺參與排泄的主要證據為何？", answer: "呼氣排出細胞代謝產生的二氧化碳", reason: "二氧化碳由血液運到肺泡並離開體外，符合代謝廢物排泄。" },
  ],
));

questions.push(
  question("BIO_R4_Q_074_01", "BIO_R4_S074", "foundation", "人體尿液主要由哪個器官形成？", ["腎臟", "肺部", "胃部", "心臟"], 0, ["腎臟處理血液中的尿素與多餘水鹽，形成尿液。", "肺主要交換並排出氣體，不會形成泌尿系統的尿液。", "胃負責儲存與消化食物，不是尿液形成器官。", "心臟推動血液循環，但不直接把血液處理成尿液。"], ["題目問尿液形成而非暫存，應選擇處理血液並形成尿液的腎臟。", "膀胱只負責暫時儲尿，即使列入選項也不能取代腎臟的形成作用。"]),
  question("BIO_R4_Q_074_02", "BIO_R4_S074", "foundation", "汗液主要由皮膚哪種構造分泌？", ["毛髮", "汗腺", "肺泡", "腎小球"], 1, ["毛髮可影響體表環境，但不是分泌汗液的腺體。", "汗腺位於皮膚，可將含水與鹽的汗液排到體表。", "肺泡位於肺內進行氣體交換，不會分泌皮膚汗液。", "腎小球參與腎臟處理血液，和皮膚出汗位置不同。"], ["把分泌物名稱和構造連結，汗液由皮膚中的汗腺形成並排出。", "汗腺分泌後還需汗液蒸發，才會有較明顯的散熱效果。"]),
  question("BIO_R4_Q_074_03", "BIO_R4_S074", "foundation", "細胞代謝產生的二氧化碳主要經哪個器官排出？", ["大腸", "膀胱", "肺部", "小腸"], 2, ["大腸主要形成糞便，並非二氧化碳排出的主要器官。", "膀胱暫存尿液，不會把血液中的二氧化碳交換到空氣。", "肺部將血中二氧化碳移入肺泡，再隨呼氣排出。", "小腸吸收養分，不能取代肺部的氣體廢物排出。"], ["由細胞到肺的二氧化碳會先經血液運送，最後跨入肺泡離開。", "此過程同時是氣體交換與排泄，不應把排泄只理解為排尿。"]),
  question("BIO_R4_Q_074_04", "BIO_R4_S074", "standard", "下列哪組器官與主要排出物配對正確？", ["腎臟－糞便", "肺－尿素尿液", "皮膚－大量二氧化碳", "肺－二氧化碳"], 3, ["糞便由消化道形成並排出，不是腎臟的主要產物。", "尿素主要由腎臟形成尿液排出，而不是由肺形成。", "皮膚主要以汗液排水鹽，二氧化碳主要由肺排出。", "肺讓血中二氧化碳進入肺泡並隨呼氣離開，配對正確。"], ["依各器官最主要的排出物判斷，肺與二氧化碳的功能連結最明確。", "有些物質可由多途徑少量排出，但不能因此忽略主要器官分工。"]),
  question("BIO_R4_Q_074_05", "BIO_R4_S074", "standard", "血中尿素持續升高，最應優先檢查哪項功能？", ["腎臟形成並排出尿液", "牙齒切碎食物", "鼻腔溫暖空氣", "心房接收血液"], 0, ["腎臟若無法有效移除尿素，含氮廢物可能在血中累積。", "牙齒咀嚼不會直接把血中尿素形成尿液排出。", "鼻腔處理吸入空氣，與尿素清除不是同一生理途徑。", "心房接收血液但不負責將其中尿素選擇性形成尿液。"], ["從異常物質反查主要排出器官，尿素累積最直接連到腎臟功能。", "循環負責把尿素送到腎臟，但真正形成尿液的處理仍由腎臟完成。"]),
  question("BIO_R4_Q_074_06", "BIO_R4_S074", "standard", "汗液在皮膚表面蒸發，最直接造成什麼？", ["製造更多尿素", "帶走體表熱量", "把氧氣變成養分", "形成糞便"], 1, ["尿素來自含氮物質代謝，不會因汗液蒸發而被製造。", "液態水蒸發需吸收熱量，可從皮膚帶走熱而協助降溫。", "汗液蒸發是物理變化，不會把氧氣化學轉成養分。", "糞便在大腸形成，與皮膚表面水分蒸發無關。"], ["流汗降溫的關鍵不是汗水存在，而是水分蒸發時吸收熱量。", "高濕環境中蒸發較慢，即使汗量多，實際降溫效率也可能較差。"]),
  question("BIO_R4_Q_074_07", "BIO_R4_S074", "standard", "肺與腎臟在排泄上的共同點為何？", ["都形成糞便", "都只排出氧氣", "都能移除體內代謝相關廢物", "都位於皮膚表面"], 2, ["糞便由消化道排遺，肺與腎臟都不負責形成糞便。", "肺主要排二氧化碳，腎臟排尿素等，並非都只排氧氣。", "肺移除二氧化碳，腎臟移除尿素等，皆參與代謝廢物排泄。", "兩器官位於體內不同位置，並不都在皮膚表面。"], ["共同點要找較高層次功能，兩者排出的具體物質不完全相同。", "多器官協同排泄能維持內在環境，不能把排泄等同單一泌尿器官。"]),
  question("BIO_R4_Q_074_08", "BIO_R4_S074", "advanced", "肺部換氣嚴重受阻，哪種廢物最先直接難以大量排出？", ["糞便纖維", "尿中尿素", "汗中鹽類", "二氧化碳"], 3, ["纖維隨消化道排遺，不依賴肺部換氣才能離開。", "尿素主要由腎臟排尿，肺換氣不是其主要排出途徑。", "鹽類可隨汗液排出，皮膚汗腺不由肺直接控制形成。", "二氧化碳須進入肺泡並隨呼氣離開，換氣受阻會直接影響。"], ["依主要排出器官配對，只有二氧化碳高度依賴肺部持續換氣。", "血液仍可把二氧化碳運到肺，但若無法呼出，最終仍會造成累積。"]),
  question("BIO_R4_Q_074_09", "BIO_R4_S074", "advanced", "高濕環境中大量流汗卻不易降溫，最合理原因為何？", ["汗液蒸發速度較慢", "腎臟停止形成尿液", "肺泡全部消失", "血液不再含水"], 0, ["環境水氣多會降低汗液蒸發速率，使帶走熱量的效果下降。", "高濕與排汗降溫差不能直接證明腎臟完全停止形成尿液。", "環境濕度不會使肺泡解剖構造在短時間內全部消失。", "人體大量流汗可能失水，但不能說血液立即完全不含水。"], ["降溫取決於蒸發量，不是只看皮膚表面有多少汗液。", "比較相同汗量在乾燥與潮濕環境的蒸發，可直接檢驗此解釋。"]),
  question("BIO_R4_Q_074_10", "BIO_R4_S074", "advanced", "若腎臟功能下降但出汗正常，為何仍不能說排泄完全正常？", ["汗液一定不含水", "汗液無法完全取代尿素排出與精細水鹽調節", "肺會因此變成腎臟", "糞便會直接進入血管"], 1, ["汗液主要成分就是水，不能說它一定完全不含水。", "腎臟對尿素與水鹽平衡有重要功能，皮膚不能完整替代。", "器官功能受損不會使肺的組織直接轉變為腎臟。", "消化道與血管有屏障，腎功能下降不會讓糞便直接入血。"], ["器官排出物有部分重疊不代表可以完全互相替代，仍要看主要功能。", "判斷整體排泄需同時評估二氧化碳、尿素和水鹽等不同物質。"]),
  question("BIO_R4_Q_074_11", "BIO_R4_S074", "transfer", "密閉艙中裝置只能移除空氣二氧化碳，最接近替代哪個器官的部分功能？", ["大腸", "胃部", "肺部", "腎臟"], 2, ["大腸主要形成與排出糞便，不處理空氣中的二氧化碳。", "胃進行食物消化，沒有把艙內二氧化碳移除的主要功能。", "肺把血中二氧化碳交換到空氣並排出，功能最接近。", "腎臟形成尿液排尿素，不以直接清除空氣二氧化碳為主。"], ["依裝置處理的物質判斷，不需要求模型外形與人體器官相同。", "裝置只替代二氧化碳移除，仍不能完成肺部氧氣交換與呼吸運動全部功能。"]),
  question("BIO_R4_Q_074_12", "BIO_R4_S074", "transfer", "某動物主要由鰓排氨，這項功能和人體哪個概念相同？", ["未消化殘餘排遺", "食物機械消化", "肺泡吸入空氣", "由器官移除代謝廢物的排泄"], 3, ["氨由代謝產生，不是未消化食物留在消化道的殘餘。", "排氨是物質移出而非把食物顆粒切小的機械消化。", "鰓排氨的題述重點不是吸入空氣或肺泡通氣。", "不同動物可用不同器官，但移除代謝廢物都屬排泄。"], ["跨物種比較時保留功能定義，不把人體器官名稱當成唯一形式。", "鰓、肺、腎或體表都可能參與排泄，關鍵仍是排出物來自代謝。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S074", "BIO_R4_S074", "organ-output-table",
  { title: "三種器官排出物紀錄", text: "研究者在相同觀察期間記錄三種器官主要排出物。數值為教學用相對量，目的在比較物質種類，不代表固定人體標準。", note: "某物質相對量為零表示本次未測得，不表示任何情況都絕對不會排出。" },
  { summary: "表格顯示腎臟排尿素與水鹽、皮膚排水鹽、肺排二氧化碳與水氣。", colorIndependent: true, dataFallback: { columns: ["器官", "尿素", "水", "鹽類", "二氧化碳"], rows: [["腎臟", "80", "70", "55", "0"], ["皮膚", "2", "35", "12", "0"], ["肺", "0", "18", "0", "95"]] } },
  [
    question("BIO_R4_SQ_074_01", "BIO_R4_S074", "standard", "依表格，哪個器官排出尿素相對量最高？", ["三者相同", "皮膚", "肺部", "腎臟"], 3, ["三組數值八十、二、零不同，不能判為相同。", "皮膚只測得相對量二，明顯不是最高值。", "肺在本次尿素欄為零，主要排出物是二氧化碳。", "腎臟尿素相對量八十，高於皮膚二與肺零。"], ["直接比較尿素欄即可判斷，腎臟是本表最主要的尿素排出器官。", "相對量不能當作固定人體比例，但可支持器官間本次功能差異。"]),
    question("BIO_R4_SQ_074_02", "BIO_R4_S074", "advanced", "哪項最能支持肺也參與排泄？", ["肺排出二氧化碳相對量最高", "肺的鹽類為零", "肺沒有尿素", "肺與皮膚名稱不同"], 0, ["二氧化碳是細胞代謝廢物，肺大量排出符合排泄定義。", "鹽類未測得不能證明肺有移除代謝廢物的功能。", "沒有排尿素只能顯示分工不同，不能單獨作為排泄正證據。", "器官名稱不同是文字事實，無法證明實際排出物來源。"], ["把二氧化碳的代謝來源與肺的高排出量相連，形成完整證據。", "排泄可由不同器官處理不同物質，不能用有無尿素作唯一標準。"]),
    question("BIO_R4_SQ_074_03", "BIO_R4_S074", "transfer", "若皮膚排水量升高但尿素仍接近二，最合理推論為何？", ["皮膚已完全取代腎臟", "出汗可增加水分排出，但未顯示大量尿素改由皮膚排出", "肺從此不排二氧化碳", "腎臟已變成皮膚"], 1, ["尿素排出仍低，不能說皮膚完整取代腎臟的主要功能。", "資料分別支持水排出增加及尿素仍低，結論範圍適當。", "皮膚排水變化不會直接使肺停止二氧化碳排出。", "器官不會因排出量變化就互相轉變組織身分。"], ["同時閱讀水與尿素兩欄，避免只看總汗量便推論所有排泄都被替代。", "真實判斷還需評估腎臟尿液與血中尿素，才能知道整體平衡。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S075", "BIO_R4_S075",
  ["描述代謝廢物由細胞經循環送到排泄器官的路徑", "由血流受阻情境推論廢物累積與排出量變化"],
  [
    { id: "BIO_R4_L_S075_SEC_01", title: "廢物先離開細胞", content: "細胞代謝產生二氧化碳與含氮廢物後，這些物質會由細胞進入組織液與微血管。若留在細胞周圍累積，可能影響內在環境。" },
    { id: "BIO_R4_L_S075_SEC_02", title: "血液負責運送", content: "循環系統把二氧化碳送到肺，把尿素等含氮廢物送到腎臟。血液是運輸媒介，心臟提供動力，血管提供通路，使組織周圍血液持續更新。" },
    { id: "BIO_R4_L_S075_SEC_03", title: "排泄器官完成移出", content: "肺讓二氧化碳由血液進入肺泡並呼出，腎臟把尿素與多餘水鹽形成尿液。循環把廢物送達，但真正跨出身體要靠相應排泄器官。" },
    { id: "BIO_R4_L_S075_SEC_04", title: "受阻位置決定結果", content: "局部血流下降時，該組織廢物帶走變慢；全身心輸出下降則可能廣泛影響運送。若腎臟或肺受損，即使血流送達，廢物仍可能難以移出。" },
  ],
  [
    { id: "BIO_R4_L_S075_EX_01", prompt: "肌肉產生的二氧化碳如何到肺？", steps: ["先由細胞進入附近微血管", "再隨靜脈回心並送到肺部"], answer: "進入血液後隨循環運到肺", why: "二氧化碳不會從腿部直接穿越身體到肺泡，而是先進入肌肉微血管，隨血液回到心臟，再被送往肺部交換並呼出。" },
    { id: "BIO_R4_L_S075_EX_02", prompt: "通往腎臟血流大減，血中尿素可能如何？", steps: ["確認尿素需由血送到腎", "推論送達量下降的結果"], answer: "尿素清除可能下降並在血中累積", why: "腎臟只能處理流經其中的血液，供血下降會減少單位時間送達的尿素量，因此即使其他組織仍持續代謝，整體清除可能降低。" },
    { id: "BIO_R4_L_S075_EX_03", prompt: "血液把廢物送到腎臟是否等於已排出體外？", steps: ["區分運送到器官與離開身體", "追蹤尿液形成及排出"], answer: "不等於，還需形成尿液並排出", why: "循環只把尿素送到腎臟，廢物仍在體內；腎臟處理後形成尿液，並經泌尿道離開身體，才完成排泄的移出步驟。" },
  ],
  [
    { belief: "代謝廢物會從細胞直接跳到肺或腎臟", whyWrong: "遠端器官之間需要血液循環運送，廢物不會跨越組織瞬間抵達。", correction: "廢物先進入微血管，再隨血流到相應排泄器官接受處理。" },
    { belief: "血液本身會把所有廢物排到體外", whyWrong: "血液負責運送，真正移出需肺氣體交換或腎臟形成尿液。", correction: "循環與排泄器官分工合作，運送到器官不等於已完成排泄。" },
    { belief: "腎臟正常時不需要血液送入尿素", whyWrong: "腎臟處理的是流經其中的血液，尿素必須先隨循環到達。", correction: "腎功能與腎血流都會影響尿素清除，兩項條件不能互相取代。" },
    { belief: "局部血流阻塞只影響氧氣，不影響廢物", whyWrong: "血液同時送入物質與帶走二氧化碳等代謝產物。", correction: "局部血流下降會使供氧減少，也會讓該處廢物移除速度下降。" },
  ],
  [
    { prompt: "細胞的代謝廢物如何到遠端排泄器官？", answer: "先進入血液並隨循環運送", reason: "血液流經組織微血管時接收廢物，再由心臟推動到肺或腎臟。" },
    { prompt: "循環把尿素送到腎臟後還缺哪一步？", answer: "腎臟形成尿液並使其排出", reason: "送達只完成運輸，尿素仍須進入尿液並離開身體才完成排泄。" },
    { prompt: "組織血流阻塞為何使廢物累積？", answer: "帶走廢物的血液更新速度下降", reason: "微血管流量降低時，二氧化碳與其他產物由組織移出的速率會變慢。" },
  ],
));

questions.push(
  question("BIO_R4_Q_075_01", "BIO_R4_S075", "foundation", "細胞產生的二氧化碳主要靠何者運到肺？", ["血液循環", "食道蠕動", "尿液流動", "皮膚角質"], 0, ["二氧化碳進入微血管後，隨血液循環到肺部排出。", "食道只推送食團到胃，不會把組織二氧化碳送到肺。", "尿液由腎臟流向體外，並非二氧化碳的運輸媒介。", "皮膚角質形成屏障，不負責全身氣體廢物運送。"], ["遠端細胞與肺之間由血管相連，血液是二氧化碳的主要運輸媒介。", "肺負責最後交換排出，但二氧化碳到肺之前需要循環運送。"]),
  question("BIO_R4_Q_075_02", "BIO_R4_S075", "foundation", "尿素由細胞相關代謝處運到腎臟，主要經過何者？", ["消化道管腔", "血管", "呼吸道", "輸尿管逆流"], 1, ["尿素已在體內，並非留在消化道管腔的食物殘餘。", "血液在血管內流動，可把尿素送到腎臟接受處理。", "呼吸道主要運送空氣，不是尿素到腎臟的通路。", "輸尿管把尿液離開腎臟送往膀胱，方向並非把尿素送入腎。"], ["尿素先經循環到腎臟，之後才隨形成的尿液進入輸尿管。", "辨認前後順序可避免把血管運輸和泌尿道排出混為一談。"]),
  question("BIO_R4_Q_075_03", "BIO_R4_S075", "foundation", "血液把二氧化碳送到肺後，下一個主要步驟為何？", ["進入胃腔", "形成糞便", "跨入肺泡並隨呼氣排出", "轉成完整食物"], 2, ["二氧化碳到肺後不會進胃，呼吸與消化管道功能不同。", "糞便由消化道殘餘形成，不是二氧化碳的排出形式。", "二氧化碳由肺微血管進肺泡，再隨呼氣離開身體。", "人體不會把代謝二氧化碳直接組成完整食物。"], ["循環送達後，肺部氣體交換才使二氧化碳真正離開血液與身體。", "這條路徑同時連結循環、呼吸與排泄三個系統的分工。"]),
  question("BIO_R4_Q_075_04", "BIO_R4_S075", "standard", "哪項最完整描述尿素排出路徑？", ["腎臟→細胞→血液", "細胞→食道→胃", "血液→肺泡→呼氣", "代謝形成→進血液→腎臟→尿液排出"], 3, ["尿素由代謝產生後到腎臟，不是由腎臟反向送回細胞形成。", "食道與胃處理食物，沒有把細胞尿素送到體外的主要功能。", "肺主要排二氧化碳，尿素不以呼氣作為主要排出途徑。", "形成、循環運送、腎臟處理與尿液排出順序完整正確。"], ["完整路徑須包含廢物來源、運輸媒介、排泄器官與離體形式。", "只寫到腎臟仍未完成，還需要尿液經泌尿道排出身體。"]),
  question("BIO_R4_Q_075_05", "BIO_R4_S075", "standard", "腿部血流阻塞時，當地二氧化碳較易累積的原因為何？", ["帶走廢物的血液流量下降", "肺泡立即全部消失", "腎臟停止製造尿液", "二氧化碳變成纖維"], 0, ["局部血液更新變慢，使細胞產生的二氧化碳較難被帶離。", "腿部血管阻塞不會使肺泡解剖構造立即全部消失。", "局部二氧化碳累積可在腎臟仍排尿時發生，兩者非直接因果。", "二氧化碳不會因血流阻塞就化學轉變成未消化纖維。"], ["血液不只送氧，也負責帶走廢物，因此阻塞同時影響雙向交換。", "題目聚焦局部結果，不能用無關器官完全停止作解釋。"]),
  question("BIO_R4_Q_075_06", "BIO_R4_S075", "standard", "腎臟功能正常但流入腎臟血量大減，可能有何結果？", ["尿素送達增加", "單位時間尿素清除可能下降", "糞便完全停止形成", "肺部不再換氣"], 1, ["供血量下降通常使送達腎臟的尿素量減少，而不是增加。", "腎臟只能處理流經的血液，血流少可能限制單位時間清除。", "腎血流變化不能直接使大腸的糞便形成完全停止。", "肺換氣有自己的呼吸機制，不會只因腎血流下降就停止。"], ["器官功能正常仍需要足夠物質送達，運輸可成為整體流程的限制。", "若血中尿素升高且腎血流低，需同時評估血流和腎組織功能。"]),
  question("BIO_R4_Q_075_07", "BIO_R4_S075", "standard", "循環系統與排泄器官的分工何者正確？", ["循環形成糞便，肺消化食物", "腎臟泵血，心臟形成尿液", "循環運送廢物，肺或腎臟使其離體", "血液直接把所有廢物穿過皮膚"], 2, ["循環不形成消化道糞便，肺也沒有消化食物的功能。", "心臟負責泵血，腎臟形成尿液，選項把功能完全對調。", "血液負責送達，排泄器官再以呼氣或尿液完成移出。", "不同廢物有特定途徑，血液不會把全部種類直接穿過皮膚。"], ["把運輸和跨出身體兩步分開，才能精確描述系統協同。", "血液到達器官不是排泄終點，仍需器官交換或形成排出物。"]),
  question("BIO_R4_Q_075_08", "BIO_R4_S075", "advanced", "血液可正常到肺，但肺泡壁無法讓二氧化碳通過，何者最合理？", ["運輸與排出都完全正常", "尿素改由肺大量排出", "血液不再流動", "二氧化碳送達肺但仍難以離體"], 3, ["氣體跨壁受阻表示排出環節異常，不能說整個流程正常。", "肺泡障礙不會使含氮尿素改成由肺大量排出。", "題幹明示血液可正常到肺，不能反向推論血流停止。", "循環完成送達，但交換障礙使二氧化碳留在血液中累積。"], ["定位流程受阻處：血液運輸正常，問題在肺泡跨膜與呼出之前。", "相同廢物累積可由運輸或器官處理不同原因造成，需依證據區分。"]),
  question("BIO_R4_Q_075_09", "BIO_R4_S075", "advanced", "要驗證血流有助帶走肌肉廢物，最適合比較何者？", ["相同肌肉在正常與降低血流時的廢物濃度", "不同人的髮色", "比較正常血流時肌肉的溫度變化", "運動鞋顏色"], 0, ["控制肌肉活動只改血流，可直接比較廢物帶走效果。", "髮色與肌肉微血管運輸廢物沒有可用的直接關係。", "溫度變化不是廢物濃度，也沒有操弄血流形成對照。", "鞋子顏色若不影響運動強度，不能檢驗循環運輸功能。"], ["實驗需把血流設為主要差異，並以廢物濃度作結果變項。", "還要監測氧供與細胞損傷，避免把代謝產生量改變誤認為運輸差異。"]),
  question("BIO_R4_Q_075_10", "BIO_R4_S075", "advanced", "某廢物在組織產生量不變，靜脈端濃度下降但組織濃度升高，可能表示什麼？", ["廢物完全未產生", "由組織進入血液的運送受阻", "排泄器官一定增強", "組織已變成肺泡"], 1, ["題幹明示產生量不變，不能說廢物完全未產生。", "組織累積且靜脈帶走量低，符合進血或局部血流受阻。", "局部資料無法證明遠端排泄器官一定增強，方向也不相符。", "濃度變化不會使組織解剖構造轉變成肺泡。"], ["同時看組織與流出血液，可區分產生量和帶走量的改變。", "若再測局部血流與膜通透性，可進一步定位是灌流或跨膜問題。"]),
  question("BIO_R4_Q_075_11", "BIO_R4_S075", "transfer", "垃圾車把垃圾送到處理場卻未處理，最像哪種情況？", ["細胞完全不產生廢物", "血液不流動", "循環送達排泄器官但器官無法移出廢物", "未消化食物正常排遺"], 2, ["模型已有垃圾被運送，代表廢物確實存在並非未產生。", "垃圾車能到處理場表示運輸存在，不類似血液完全不流動。", "送達正常但處理失敗，對應排泄器官功能受阻。", "垃圾來自製程後運輸，不是消化道內未吸收食物殘餘。"], ["類比需分辨運送與處理兩環節，不能看到累積就一律怪罪交通。", "模型顯示循環正常仍不足以完成排泄，排泄器官也必須正常。"]),
  question("BIO_R4_Q_075_12", "BIO_R4_S075", "transfer", "人工腎裝置要有效清除尿素，除了可透析膜還需要什麼？", ["讓血液完全靜止", "只改裝置外殼顏色", "把尿素變成糞便", "讓含尿素血液持續流經裝置"], 3, ["血液完全靜止會使新尿素難以送達膜面，降低持續清除。", "外殼顏色不會建立尿素濃度差或運送新的血液。", "人工腎清除溶質，不會把尿素轉變成消化道糞便。", "持續血流可把尿素送到膜面並帶回處理後血液，維持運輸。"], ["有效系統同時需要可交換的處理面與持續更新的運輸液體。", "這項設計再次顯示循環和排泄處理互相依賴，任一缺少都會限制清除。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S075", "BIO_R4_S075", "waste-transport-table",
  { title: "肌肉血流與廢物濃度", text: "研究者讓兩組相同肌肉以相同強度收縮五分鐘。甲組血流維持正常，乙組局部血流降為甲的四分之一；記錄肌肉間液與流出靜脈中的廢物相對濃度。", note: "兩組初始濃度相同，數值越高表示本次測得的廢物越多。" },
  { summary: "表格顯示低血流組的肌肉間液廢物較高，而流出靜脈帶走總量較低。", colorIndependent: true, dataFallback: { columns: ["組別", "相對血流", "肌肉間液廢物濃度", "靜脈每分鐘帶走量"], rows: [["甲", "100%", "18", "64"], ["乙", "25%", "47", "22"]] } },
  [
    question("BIO_R4_SQ_075_01", "BIO_R4_S075", "standard", "哪組肌肉間液廢物濃度較高？", ["兩組相同", "甲組", "乙組", "資料未量濃度"], 2, ["兩組數值相差二十九，並不是相同。", "甲組十八較低，不能判為濃度較高。", "乙組濃度四十七，高於甲組十八。", "表格有肌肉間液廢物濃度欄，資料已直接量測。"], ["直接比較相同單位的濃度欄，乙組是較高者。", "此結果還需結合血流與帶走量，才能解釋為何發生累積。"]),
    question("BIO_R4_SQ_075_02", "BIO_R4_S075", "advanced", "乙組廢物累積最合理的解釋為何？", ["乙組完全沒有細胞代謝", "廢物全部變成氧氣", "乙組肺泡數量增加", "血流下降使廢物帶走速度降低"], 3, ["肌肉仍以相同強度收縮，不支持完全沒有代謝與廢物產生。", "代謝廢物不會因血流下降就全部轉變成氧氣。", "局部肌肉資料沒有測量肺泡數量，也不能解釋組織累積。", "乙血流只有四分之一且每分鐘帶走量低，符合移除變慢。"], ["低血流、低帶走量與高組織濃度三項資料共同支持運輸限制。", "這是本實驗下的因果推論，仍應注意低氧可能改變廢物產生種類。"]),
    question("BIO_R4_SQ_075_03", "BIO_R4_S075", "transfer", "若乙組恢復正常血流，最合理的短期預測為何？", ["帶走量可能上升，間液濃度逐步下降", "肌肉立即變成腎臟", "廢物一定永久增加", "循環從此停止"], 0, ["更多血液更新可接收廢物，使帶走量增加並降低累積。", "血流改變不會使肌肉組織轉變成形成尿液的腎臟。", "運輸恢復通常有助清除，不能預測廢物必定永久增加。", "恢復正常血流和循環停止方向相反，不能同時成立。"], ["預測需沿同一機制反推：運輸限制解除後，廢物移除應改善。", "使用逐步下降較合理，因已累積的廢物仍需時間進入血液並被排泄器官移除。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S076", "BIO_R4_S076",
  ["計算飲水、食物與代謝產水相對於尿液、汗液、呼氣及糞便的水分收支", "依活動與環境資料判斷補水需求及短期水分平衡"],
  [
    { id: "BIO_R4_L_S076_SEC_01", title: "水分有多種來源", content: "人體水分來源包括飲水、食物中的水及少量代謝產水。比較收支時應把同一段時間內各來源相加，不能只看直接喝下的水量。" },
    { id: "BIO_R4_L_S076_SEC_02", title: "水分由多途徑流失", content: "尿液、汗液、呼出氣水氣與糞便都會帶走水分。即使沒有流汗或排尿，呼吸與皮膚仍可能持續造成不易察覺的水分流失。" },
    { id: "BIO_R4_L_S076_SEC_03", title: "收支差代表趨勢", content: "同一時段攝取總量減去流失總量，可估計水分淨變化。負值表示該時段流失較多，需留意補充；正值也不代表水可無限制累積，身體會調節尿量。" },
    { id: "BIO_R4_L_S076_SEC_04", title: "活動與環境改變需求", content: "運動、高溫或乾燥環境常增加汗液或呼吸水分流失。補水策略要考慮活動時間、強度、環境與個體狀態，不能用固定單一數字套用所有人。" },
  ],
  [
    { id: "BIO_R4_L_S076_EX_01", prompt: "兩小時攝取700毫升、流失900毫升，水分淨變化為何？", steps: ["用攝取總量減去流失總量", "判斷正負值代表的方向"], answer: "淨減少200毫升", why: "七百減九百等於負二百，表示這兩小時流失量比攝取量多二百毫升；此為估計收支，不表示所有水分都來自血液。" },
    { id: "BIO_R4_L_S076_EX_02", prompt: "沒有排尿是否代表完全沒有水分流失？", steps: ["列出尿液以外的流失途徑", "檢查呼吸與皮膚是否仍運作"], answer: "不是，仍可經汗液、皮膚、呼氣與糞便失水", why: "尿液只是水分流失途徑之一；呼出氣含水氣，皮膚也會有水分散失，因此短時間沒有排尿仍不能把總流失量視為零。" },
    { id: "BIO_R4_L_S076_EX_03", prompt: "相同飲水量下，炎熱跑步者為何較需留意補水？", steps: ["比較環境與活動造成的汗量", "把增加的流失納入總收支"], answer: "汗液與呼吸流失可能增加，使淨水分更易下降", why: "炎熱運動會提高散熱與換氣需求，汗液及呼吸水分常增加；若攝取量不變，總流失可能超過攝取而造成較大的負收支。" },
  ],
  [
    { belief: "水分攝取只包括直接喝水", whyWrong: "食物含水與代謝產水也可成為人體水分來源。", correction: "計算總攝取時應納入飲水、食物水分與題目提供的代謝產水。" },
    { belief: "一天沒有流汗就完全不會失水", whyWrong: "呼氣、皮膚不顯性散失、尿液與糞便仍可帶走水分。", correction: "總流失需逐項相加，不能只用肉眼可見的汗液代表全部途徑。" },
    { belief: "攝取比流失多就可以無限制繼續喝水", whyWrong: "身體調節有範圍，短時間過量攝取也可能造成水鹽失衡。", correction: "補水應依實際流失與健康情況調整，不追求越多越好的單一目標。" },
    { belief: "同樣活動下每個人的失水量一定相同", whyWrong: "體型、適應、衣著、溫濕度與活動強度都可能造成差異。", correction: "個人補水要結合量測與症狀，群體平均值不能取代每人的狀態。" },
  ],
  [
    { prompt: "水分收支如何計算？", answer: "同時段攝取總量減去流失總量", reason: "統一時間並加總所有來源與途徑，才能判斷水分淨增加或淨減少。" },
    { prompt: "沒有排尿仍可能由哪些途徑失水？", answer: "呼氣、皮膚或汗液及糞便", reason: "人體持續呼吸且體表會散失水分，因此尿量零不等於總流失量零。" },
    { prompt: "炎熱運動為何常增加補水需求？", answer: "汗液與呼吸水分流失通常上升", reason: "身體為散熱與供應活動提高出汗和換氣，使總流失量更容易超過攝取。" },
  ],
));

questions.push(
  question("BIO_R4_Q_076_01", "BIO_R4_S076", "foundation", "下列哪項可成為人體水分的攝取來源？", ["食物中的水分", "呼出的水氣", "排出的尿液", "滴落的汗液"], 0, ["食物所含水分經消化道吸收後，可補充人體水分。", "呼出水氣由身體離開，屬流失而不是攝取來源。", "尿液將水分排出體外，不能計入同時段攝取量。", "汗液離開皮膚代表水分流失，不會增加體內水量。"], ["攝取方向是由外界進入體內，食物水分符合此方向。", "計算時可把飲水與食物水分相加，但不能把排出物重複算成來源。"]),
  question("BIO_R4_Q_076_02", "BIO_R4_S076", "foundation", "下列哪項屬於人體水分流失途徑？", ["喝水", "呼出水氣", "吃水果", "代謝產水"], 1, ["喝水使水分進入身體，應列在攝取而非流失。", "呼出氣帶有水蒸氣，會讓水分由呼吸道離開身體。", "水果中的水被吸收後可補充人體，不是流失途徑。", "代謝反應形成的水是來源，並非水離開身體的路徑。"], ["流失必須有水分離開人體，呼出水氣符合這個判準。", "不易看到的呼吸失水也要納入，不能只計算尿液與明顯汗液。"]),
  question("BIO_R4_Q_076_03", "BIO_R4_S076", "foundation", "某時段攝取600毫升、流失450毫升，淨變化為何？", ["減少1050毫升", "減少150毫升", "增加150毫升", "增加1050毫升"], 2, ["收支應相減而非相加，六百與四百五十相加不代表淨減少。", "攝取大於流失，淨值不會是負一百五十毫升。", "六百減四百五十等於正一百五十，表示淨增加。", "一千零五十是兩數總和，並非攝取減流失的收支結果。"], ["先固定公式為攝取減流失，再依正值判定淨增加。", "此結果只描述該時段估計，不代表身體會永久保留全部一百五十毫升。"]),
  question("BIO_R4_Q_076_04", "BIO_R4_S076", "standard", "某時段攝取800毫升、尿汗等共流失1100毫升，何者正確？", ["淨增加300毫升", "兩者完全平衡", "淨增加1900毫升", "淨減少300毫升"], 3, ["攝取量小於流失量，淨變化不可能是增加三百毫升。", "八百與一千一百不相等，不能判定完全平衡。", "一千九百是兩者相加，不是身體水分淨增加量。", "八百減一千一百為負三百，代表淨減少三百毫升。"], ["負收支表示該時段流失較多，需要依狀態評估補水。", "計算必須使用相同時間與相同體積單位，才能直接相減。"]),
  question("BIO_R4_Q_076_05", "BIO_R4_S076", "standard", "沒有排尿的兩小時內，為何仍不能把水分流失記為零？", ["仍可能經呼氣與皮膚散失水分", "心臟會製造尿液", "食物水分一定消失", "血液完全不含水"], 0, ["呼吸持續帶出水氣，皮膚也可能有汗液或不顯性失水。", "尿液主要由腎臟形成，心臟不會取代腎臟製尿。", "是否進食與食物含水需實際記錄，不能說一定全部消失。", "血液以水為重要成分，兩小時無尿不會使血液完全無水。"], ["總流失是多途徑加總，任何一項暫時為零都不能代表整體為零。", "若要估算可量體重變化並記錄飲食排出，但仍須考慮量測誤差。"]),
  question("BIO_R4_Q_076_06", "BIO_R4_S076", "standard", "炎熱環境運動時，哪項變化最可能使水分流失增加？", ["小腸停止吸收", "汗液分泌增加", "肺泡變成腎臟", "尿素全部消失"], 1, ["小腸不會因一般炎熱運動就必然停止所有水分吸收。", "出汗增加可使更多水到達體表並在蒸發或滴落時流失。", "環境變熱不會讓肺泡的組織直接轉變為腎臟。", "尿素是否存在與汗液總水量不是同一項直接變化。"], ["高溫運動提高散熱需求，汗液通常是增加失水的重要途徑。", "補水量仍需依活動時間、汗量與健康狀況調整，不能套用固定數字。"]),
  question("BIO_R4_Q_076_07", "BIO_R4_S076", "standard", "比較兩人的水分收支，最重要的資料處理為何？", ["只比較飲水瓶顏色", "忽略食物中的水", "使用相同時段並加總各攝取與流失途徑", "只選流汗較多者"], 2, ["瓶子顏色不代表飲水體積，也不影響各項流失量。", "食物含水可能是重要來源，忽略會低估總攝取。", "統一時間與完整加總可避免分母不同或漏項造成誤判。", "只挑某一人不能完成兩人公平比較，也忽略其他流失途徑。"], ["收支比較需要同一時間尺度與同一單位，並避免只看單一途徑。", "若有估計值也應標示不確定性，不能把不完整紀錄當成精確總量。"]),
  question("BIO_R4_Q_076_08", "BIO_R4_S076", "advanced", "兩人飲水皆500毫升，甲汗400、乙汗100毫升。能否只據此判定甲淨失水較多？", ["能，因其他途徑必定相同", "能，因尿量永遠是零", "能，因食物完全不含水", "尚不能，還需尿液、呼氣、食物等完整收支"], 3, ["題目沒有證明其他來源與流失相同，不能自行補上此條件。", "兩人的尿量沒有提供，也不可能宣稱永遠都是零。", "食物通常可能含水，題目未說兩人食物水分皆為零。", "汗量只是總收支的一部分，其他項目可能改變最終淨值。"], ["局部資料可說甲汗液流失較多，但不能直接等同總水分淨減少較多。", "精確結論要和測量範圍一致，缺少的收支項目應明確列出。"]),
  question("BIO_R4_Q_076_09", "BIO_R4_S076", "advanced", "某人短時間水分攝取高於流失，最合理的身體反應可能為何？", ["之後尿量增加以協助調節", "所有水永久留在細胞", "肺停止排二氧化碳", "血液變成固體"], 0, ["身體可調整腎臟排水，使較多水隨尿液離開以維持平衡。", "水分會在區室間移動並受調節，不會全部永久困在細胞。", "水分正收支不會直接要求肺停止必要的二氧化碳排出。", "生理範圍內水分變化不會使流動血液突然變成固體。"], ["恆定調節會回應偏差，因此短期正收支可能伴隨後續排水增加。", "題目用可能而非必然，因實際反應還受鹽分、荷爾蒙與腎功能影響。"]),
  question("BIO_R4_Q_076_10", "BIO_R4_S076", "advanced", "哪項量測最能估計一場運動的總體失水趨勢？", ["運動衣顏色", "控制飲水與排尿後比較運動前後體重", "只數呼吸一次", "記錄鞋帶長度"], 1, ["衣服顏色不能量出水分由身體離開的總質量。", "控制進出量後的體重下降可近似反映短期總水分損失。", "單次呼吸不能代表整場運動的汗液、尿液與呼吸總失水。", "鞋帶長度與人體水分收支沒有可用的直接關係。"], ["短期體重法可整合多途徑失水，但需扣除期間飲水與排出物質量。", "量測前後應使用同一台秤與相似衣著，降低器材和濕衣造成的誤差。"]),
  question("BIO_R4_Q_076_11", "BIO_R4_S076", "transfer", "水槽有進水與多個排水口，最適合類比哪個概念？", ["只有飲水重要", "只有尿液流失", "水分平衡由多種攝取與流失共同決定", "身體水量永遠不變"], 2, ["人體還有食物水分等來源，不能只類比單一進水口。", "汗液、呼氣與糞便也會失水，不能只看尿液排出口。", "總水量變化取決於所有進入與離開流量的差，類比合理。", "若進出量不同，水槽液面會改變，不能代表水量永遠不變。"], ["模型重點是多個流量共同決定淨變化，而不是器官外形相同。", "人體還有調節回饋，水槽若沒有控制器就不能呈現全部恆定機制。"]),
  question("BIO_R4_Q_076_12", "BIO_R4_S076", "transfer", "登山者在乾冷空氣中汗不明顯仍逐漸缺水，最合理原因為何？", ["沒有汗就不會失水", "水只會經糞便流失", "冷空氣能製造體內全部水", "呼吸與不顯性皮膚失水仍持續，且水氣可能快速蒸散"], 3, ["肉眼沒看到汗不代表呼吸與皮膚水分流失停止。", "人體還有尿液、呼吸與皮膚等途徑，不只糞便會失水。", "冷空氣不會替人體製造所需的全部水分並補足收支。", "乾燥空氣有利水氣散失，呼吸頻率增加時呼吸失水也可能上升。"], ["可見汗量不是總失水的完整指標，環境會改變水分蒸散速度。", "登山補水應結合時間、尿色與個人狀態，而不是等待口渴或明顯汗水才處理。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S076", "BIO_R4_S076", "water-balance-table",
  { title: "四小時健行的水分收支", text: "學生記錄健行四小時內的水分來源與流失。食物水分與飲水均已量測；汗液依體重和衣物變化估計，呼氣及其他流失依量測模型估計。", note: "數值皆為毫升，估計值可能有誤差，但可用來比較本次收支方向。" },
  { summary: "表格列出飲水、食物水分合計攝取一千一百毫升，以及尿、汗、呼氣其他合計流失一千五百毫升。", colorIndependent: true, dataFallback: { columns: ["類別", "項目", "水量（毫升）"], rows: [["攝取", "飲水", "900"], ["攝取", "食物水分", "200"], ["流失", "尿液", "180"], ["流失", "汗液", "1050"], ["流失", "呼氣與其他", "270"]] } },
  [
    question("BIO_R4_SQ_076_01", "BIO_R4_S076", "standard", "本次健行的總攝取量是多少？", ["900毫升", "1100毫升", "1500毫升", "400毫升"], 1, ["九百只計飲水，漏掉食物提供的二百毫升水分。", "飲水九百加食物水分二百，總攝取為一千一百毫升。", "一千五百是三項流失量的合計，不是攝取總量。", "四百是收支差的絕對值，不能當作總攝取量。"], ["攝取欄需把所有來源相加，不能只使用最明顯的飲水資料。", "先分清攝取與流失分類，再分別加總，可降低把不同方向數值混加的錯誤。"]),
    question("BIO_R4_SQ_076_02", "BIO_R4_S076", "advanced", "本次水分淨變化最接近何者？", ["增加2600毫升", "增加400毫升", "減少400毫升", "完全平衡"], 2, ["二千六百是攝取與流失總量相加，並非淨變化。", "淨值為負而不是正，不能判成增加四百毫升。", "攝取一千一百減流失一千五百，得到負四百毫升。", "兩個總量相差四百，並沒有達到完全平衡。"], ["使用攝取減流失公式，負值表示本次健行估計淨失水。", "結果含估計誤差，但流失高於攝取的方向仍可作為補水評估線索。"]),
    question("BIO_R4_SQ_076_03", "BIO_R4_S076", "transfer", "若下次環境更熱且其他條件相同，最適合優先調整什麼？", ["減少所有飲水", "忽略汗液資料", "把流失量改記為零", "依增加的汗液流失規畫額外補水並持續監測"], 3, ["更熱常增加出汗，減少飲水可能使負收支更加明顯。", "汗液是本表最大流失項，不能在高溫情境反而忽略。", "改寫紀錄不會讓真實水分停止流失，也破壞資料可信度。", "按實測汗量調整並監測個人狀態，比固定補水量更合理。"], ["預測由機制出發：溫度升高可能提高汗量，因此需評估增加的流失。", "補水仍不可無限制，長時間大量出汗時也需考慮鹽分與專業健康建議。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S077", "BIO_R4_S077",
  ["說明出汗、汗液蒸發與皮膚血流改變在體溫調節中的作用", "依溫度、濕度與皮膚血流資料推論散熱效果"],
  [
    { id: "BIO_R4_L_S077_SEC_01", title: "體溫偏高啟動散熱", content: "運動或環境炎熱使核心體溫上升時，身體可增加汗液分泌與皮膚血流。這些反應通常有助把更多熱量送到體表並散失。" },
    { id: "BIO_R4_L_S077_SEC_02", title: "蒸發才真正帶走熱", content: "汗液由液態變成水蒸氣需要吸收熱量，因此蒸發能降溫。若濕度高、衣物不透氣或汗水直接滴落，分泌量雖多，實際蒸發與散熱可能較少。" },
    { id: "BIO_R4_L_S077_SEC_03", title: "皮膚血流調節散熱", content: "皮膚血管擴張可增加流到體表附近的溫暖血液，促進與環境交換熱量；寒冷時皮膚血流下降可減少熱量送到體表，但不能完全阻止散熱。" },
    { id: "BIO_R4_L_S077_SEC_04", title: "調節有範圍與代價", content: "出汗會造成水分與鹽類流失，環境溫度接近或高於皮膚時，非蒸發散熱也會受限。體溫調節不是無限有效，極端環境仍可能造成危險。" },
  ],
  [
    { id: "BIO_R4_L_S077_EX_01", prompt: "同樣汗量下，乾燥環境為何常比潮濕環境涼？", steps: ["比較兩環境的汗液蒸發速度", "連結蒸發與吸熱"], answer: "乾燥環境汗液較易蒸發並帶走更多熱", why: "空氣相對乾燥時可接納更多水蒸氣，汗液較容易由液態變氣態；蒸發過程吸收皮膚熱量，因此相同分泌量可有不同降溫效果。" },
    { id: "BIO_R4_L_S077_EX_02", prompt: "核心體溫升高時皮膚血流增加有何意義？", steps: ["追蹤熱量由核心到體表的移動", "判斷體表交換的影響"], answer: "把更多熱量帶到皮膚以利散失", why: "血液可運送熱量，皮膚血流增加使較多溫暖血液接近體表；在環境允許時，熱可透過輻射、傳導、對流與蒸發散失。" },
    { id: "BIO_R4_L_S077_EX_03", prompt: "寒冷時皮膚血流下降是否代表血液停止流動？", steps: ["區分下降與完全停止", "思考皮膚仍需基本供血"], answer: "不是，只是流向皮膚的血量減少", why: "血管收縮可降低皮膚血流以減少熱散失，但皮膚組織仍需氧氣與養分；生理調節通常改變程度，不會等同血流完全歸零。" },
  ],
  [
    { belief: "只要流汗就一定有效降溫", whyWrong: "汗液若未蒸發而直接滴落，帶走熱量的效果會較有限。", correction: "判斷散熱要看汗液蒸發量與環境濕度，不能只看分泌量。" },
    { belief: "高溫時皮膚血流增加是為了把熱留在核心", whyWrong: "更多血液到皮膚通常會把核心熱量送向體表，促進散失。", correction: "高溫時皮膚血管擴張有助散熱，低溫時血流下降較有助保溫。" },
    { belief: "寒冷時皮膚血管完全封閉最好", whyWrong: "皮膚仍需基本血流供應，完全阻斷會造成組織缺氧與損傷。", correction: "正常反應是調低而非完全停止皮膚血流，在保溫與組織需求間平衡。" },
    { belief: "體溫調節能克服任何極端環境", whyWrong: "散熱和產熱能力都有上限，極端高低溫可超過調節範圍。", correction: "恆定是在一定條件內調節，極端環境仍需衣著、補水或離開暴露。" },
  ],
  [
    { prompt: "汗液如何真正帶走體表熱量？", answer: "汗液蒸發時吸收熱量", reason: "液態水轉為水蒸氣需要能量，這些能量可由皮膚表面提供。" },
    { prompt: "高溫時皮膚血流增加有何作用？", answer: "把更多熱量運到體表散失", reason: "血液把核心產生的熱帶到皮膚附近，可增加與環境交換熱量的機會。" },
    { prompt: "高濕為何降低汗液散熱效率？", answer: "空氣接近飽和使汗液較難蒸發", reason: "蒸發量下降時吸收並帶走的熱量也會減少，即使皮膚汗水很多。" },
  ],
));

questions.push(
  question("BIO_R4_Q_077_01", "BIO_R4_S077", "foundation", "汗液協助降溫的主要物理過程為何？", ["蒸發", "凝固", "結冰", "沉澱"], 0, ["汗液蒸發時吸收皮膚熱量，可協助降低體表溫度。", "凝固是液體變固體，不是一般流汗時帶走熱量的主要方式。", "皮膚汗液通常不靠結冰調節體溫，結冰反而可能造成傷害。", "沉澱描述溶質析出，不能解釋汗水散熱的主要機制。"], ["流汗本身只是把水送到體表，真正顯著散熱需經蒸發。", "把狀態變化和能量方向連結，可理解為何濕度會影響降溫。"]),
  question("BIO_R4_Q_077_02", "BIO_R4_S077", "foundation", "核心體溫偏高時，皮膚血流通常如何改變以利散熱？", ["完全停止", "增加", "永久消失", "變成尿液"], 1, ["完全停止會使皮膚缺乏供血，不是正常散熱調節。", "皮膚血流增加可把更多核心熱量運到體表附近散失。", "血管不會因體溫升高便永久消失，調節通常可逆。", "血液與尿液是不同液體，皮膚血流不會直接轉變成尿液。"], ["高溫時皮膚血管擴張與血流增加，方向上有助體表散熱。", "此反應是否足夠仍受環境溫度與濕度限制，不能保證永遠有效。"]),
  question("BIO_R4_Q_077_03", "BIO_R4_S077", "foundation", "高濕環境會降低哪項散熱過程的效率？", ["尿液形成", "食物消化", "汗液蒸發", "血球製造"], 2, ["尿液形成主要由腎臟調節，並非高濕直接限制的體表過程。", "食物消化不以空氣濕度作為直接主要限制因素。", "空氣水氣多時汗液較難蒸發，因此蒸發散熱效率下降。", "血球製造不會因體表濕度升高而成為本題散熱限制。"], ["高濕影響空氣接納水蒸氣的能力，因此直接作用在蒸發。", "汗量可同樣很多，但若蒸發比例低，實際帶走熱量便會較少。"]),
  question("BIO_R4_Q_077_04", "BIO_R4_S077", "standard", "寒冷時皮膚血流下降，最合理的功能為何？", ["增加汗液蒸發", "把更多熱送到體表", "使皮膚完全缺氧", "減少核心熱量送到體表散失"], 3, ["寒冷時通常不需靠增加蒸發來散熱，方向與保溫需求相反。", "更多熱送到體表會增加散失，不利寒冷環境維持核心體溫。", "正常調節是降低血流，不是讓皮膚完全沒有氧氣供應。", "流向皮膚的溫暖血液減少，可降低體表熱交換而協助保溫。"], ["由血液運熱概念反推，皮膚血流下降能減少核心到體表的熱輸送。", "使用減少而不是停止，才能符合組織仍需基本血流的生理事實。"]),
  question("BIO_R4_Q_077_05", "BIO_R4_S077", "standard", "同樣分泌500毫升汗液，哪種情況通常散熱較佳？", ["較多汗液蒸發而非滴落", "汗液全部留在密閉衣物內", "空氣濕度接近飽和", "皮膚完全沒有血流"], 0, ["較多水分蒸發會吸收更多熱量，散熱效果通常較佳。", "密閉衣物阻礙水氣散出，會降低汗液持續蒸發的效率。", "高濕空氣不易接納更多水氣，蒸發通常較慢。", "皮膚無血流會造成組織損傷，也缺少核心熱量運到體表。"], ["比較的是實際蒸發量，不是汗腺分泌到皮膚的總量。", "通風與濕度可改變同樣汗量的去向，因此也改變帶走的熱量。"]),
  question("BIO_R4_Q_077_06", "BIO_R4_S077", "standard", "皮膚血管擴張如何協助散熱？", ["使血液停止流動", "讓更多溫暖血液接近體表", "把汗液送入膀胱", "製造更多食物"], 1, ["血管擴張通常增加而非停止局部血流。", "更多溫暖血液到皮膚，可提高熱量向環境散失的機會。", "汗液由汗腺到體表，不會由皮膚血管送入膀胱。", "血管調節熱輸送，不具有製造食物的功能。"], ["血液是熱量運輸媒介，血管口徑能改變到達體表的流量。", "散熱效果還需環境允許，若外界更熱，非蒸發途徑可能受限。"]),
  question("BIO_R4_Q_077_07", "BIO_R4_S077", "standard", "下列哪項最能區分汗液分泌量與散熱量？", ["兩者永遠完全相等", "汗液越鹹散熱一定越多", "只有蒸發部分會有效吸收較多熱量", "汗液滴落時吸熱最多"], 2, ["部分汗水可能滴落或留在衣物，分泌量不等於蒸發量。", "鹽度不是本題決定蒸發熱量的唯一因素，不能說越鹹越多。", "蒸發需吸收汽化能，因此蒸發比例才更直接連到散熱。", "滴落水分未發生相同程度蒸發，通常不會帶走最多熱量。"], ["分清汗腺產出與水分相變兩步，可解釋同汗量不同散熱效果。", "若要量散熱，可同時記錄蒸發量、環境與皮膚溫度，而不只量汗重。"]),
  question("BIO_R4_Q_077_08", "BIO_R4_S077", "advanced", "外界溫度高於皮膚且濕度很高時，哪項風險最合理？", ["身體一定快速結冰", "汗液一定全部蒸發", "核心完全不產熱", "散熱受限，核心體溫可能持續升高"], 3, ["高溫環境不會使身體必然快速結冰，方向完全相反。", "高濕會降低蒸發，不能說汗液一定全部蒸發。", "細胞代謝仍會產熱，不會因外界熱便使核心完全停止產熱。", "非蒸發散熱與蒸發都受限時，產熱可能超過散熱而升溫。"], ["體溫取決於產熱和散熱差，兩種主要散熱都受限時需警覺熱傷害。", "生理調節有上限，不能因已出汗便假設核心體溫必然下降。"]),
  question("BIO_R4_Q_077_09", "BIO_R4_S077", "advanced", "甲皮膚血流增加但汗液未蒸發，乙血流增加且汗液大量蒸發，誰通常散熱較多？", ["乙，因熱輸送與蒸發兩環節都運作", "甲，因未蒸發的汗一定吸熱更多", "兩者必定完全相同", "無法比較任何機制"], 0, ["乙同時把熱送到皮膚並由蒸發帶走，通常散熱較完整。", "未蒸發汗液缺少汽化吸熱，不能說一定比蒸發汗帶走更多熱。", "兩者蒸發條件不同，沒有理由必定得到完全相同散熱。", "雖無精確熱量，仍可依蒸發機制比較合理方向。"], ["串連血液運熱與汗液蒸發，可判斷兩個環節都有效時較利散熱。", "若要量化仍需皮膚溫度、環境與蒸發量，但不妨礙本題方向判斷。"]),
  question("BIO_R4_Q_077_10", "BIO_R4_S077", "advanced", "要研究濕度對汗液散熱的影響，哪個設計最合適？", ["同時改溫度、風速與活動", "固定溫度風速與活動，只改濕度並量蒸發量", "只問受試者喜歡哪種天氣", "每組用不同量測時間"], 1, ["多個環境與活動條件同時改變，無法把結果歸因於濕度。", "控制其他因素只改濕度，可比較它對蒸發與體溫的影響。", "主觀喜好不能取代汗液蒸發量與體溫等客觀資料。", "量測時間不同又不換算會使總蒸發量無法公平比較。"], ["單一變因設計讓濕度成為主要差異，蒸發量則是直接結果。", "人體研究還需補水與安全監測，不能為控制實驗忽略熱傷害風險。"]),
  question("BIO_R4_Q_077_11", "BIO_R4_S077", "transfer", "散熱器內熱水流向表面鰭片，最接近人體哪項機制？", ["尿素形成", "食物排遺", "皮膚血流把核心熱帶到體表", "肺泡把氧變成熱"], 2, ["尿素由含氮物質代謝形成，與熱水流向表面無相似功能。", "排遺是消化道殘餘排出，不能類比熱量運送。", "血液將核心熱運到皮膚，功能上類似流體把熱帶到散熱表面。", "肺泡只交換氣體，不會把氧氣直接轉變成熱量。"], ["類比重點是流動液體運送熱到較大交換表面，而不是器材外形。", "人體還會用出汗蒸發，單純散熱器模型不能呈現全部體溫調節。"]),
  question("BIO_R4_Q_077_12", "BIO_R4_S077", "transfer", "防水不透氣衣使汗液留在皮膚，何者最合理？", ["汗量存在所以一定充分降溫", "衣物會讓血液變成汗", "核心體溫必定降到零", "蒸發受阻可能降低散熱並增加熱壓力"], 3, ["汗液若不能蒸發，分泌量多仍不保證有效降溫。", "血液供應汗腺所需物質，但不會整體直接變成汗液。", "衣著不會使人體核心溫度降到不可能的零度。", "水氣難離開使蒸發吸熱下降，活動時可能增加熱累積。"], ["衣物透氣性會改變汗液去向，因此影響蒸發而非只影響汗量。", "實際風險還受環境、活動和衣物設計影響，應以體溫與症狀監測。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S077", "BIO_R4_S077", "heat-loss-table",
  { title: "濕度與汗液散熱實驗", text: "同一受試者在相同室溫、風速與固定腳踏強度下，分別於低濕與高濕環境運動二十分鐘。研究者記錄汗液分泌量、實際蒸發量與核心體溫變化。", note: "兩次測試間充分休息，起始核心體溫相同。" },
  { summary: "表格顯示高濕時汗液分泌較多但蒸發較少，核心體溫上升幅度較大。", colorIndependent: true, dataFallback: { columns: ["環境", "汗液分泌量（毫升）", "蒸發量（毫升）", "核心體溫變化（攝氏度）"], rows: [["低濕", "360", "310", "+0.4"], ["高濕", "430", "150", "+1.1"]] } },
  [
    question("BIO_R4_SQ_077_01", "BIO_R4_S077", "standard", "哪個環境的汗液實際蒸發量較多？", ["低濕", "高濕", "兩者相同", "表中沒有蒸發資料"], 0, ["低濕蒸發三百一十毫升，高於高濕的一百五十毫升。", "高濕分泌量雖高，但實際蒸發量反而較低。", "兩組蒸發量相差一百六十毫升，並非相同。", "表格明確列有實際蒸發量，不能說沒有資料。"], ["分泌量與蒸發量分列，作答時應直接比較蒸發欄。", "高濕出汗更多仍蒸發較少，正好顯示汗量不等於散熱量。"]),
    question("BIO_R4_SQ_077_02", "BIO_R4_S077", "advanced", "高濕組核心體溫上升較多，最合理原因為何？", ["高濕組完全沒有出汗", "蒸發量較少，帶走的熱量較少", "高濕使心臟停止", "低濕組沒有細胞代謝"], 1, ["高濕組分泌四百三十毫升汗液，不能說完全沒有出汗。", "高濕組蒸發少，蒸發吸熱散失的熱量可能較低。", "表格沒有心臟停止證據，受試者仍完成固定運動。", "兩次皆進行相同活動，低濕組細胞仍會代謝產熱。"], ["三項資料形成一致機制：高濕、低蒸發、較大核心升溫。", "這是控制條件下的合理推論，若量測總散熱可提供更直接的能量證據。"]),
    question("BIO_R4_SQ_077_03", "BIO_R4_S077", "transfer", "若增加高濕組風速，最合理預測為何？", ["汗液一定停止分泌", "核心體溫必定降到零", "蒸發可能增加，使升溫幅度下降", "所有水分立即回到腎臟"], 2, ["風速增加可能促進蒸發，但不表示汗腺一定完全停止分泌。", "生理調節不會使核心體溫降到零度的不可能狀態。", "移走皮膚附近濕空氣可促進蒸發，因而可能改善散熱。", "體表汗水不會因風吹就全部立即逆向回到腎臟。"], ["預測以風速降低皮膚表面水氣堆積的機制為基礎，但仍需實驗驗證。", "使用可能保留濕度、衣著與個人反應等仍會影響結果的條件。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S078", "BIO_R4_S078",
  ["描述受器、神經系統、內分泌訊號與效應器官在調節中的分工", "依反應速度、傳遞路徑與器官變化判斷協調環節"],
  [
    { id: "BIO_R4_L_S078_SEC_01", title: "感受與整合變化", content: "受器可感受體內或外界變化，將資訊送到神經系統相關中樞。中樞整合目前狀態與目標範圍，再透過神經或內分泌途徑調整器官活動。" },
    { id: "BIO_R4_L_S078_SEC_02", title: "神經訊號快速明確", content: "神經訊號沿特定神經路徑傳遞，通常反應較快速，可精確控制肌肉或腺體。神經只傳達調節指令，真正收縮或分泌仍由效應器完成。" },
    { id: "BIO_R4_L_S078_SEC_03", title: "內分泌訊號隨血液傳遞", content: "內分泌腺分泌荷爾蒙進入血液，只有具有相應受器的目標細胞會作出特定反應。荷爾蒙作用常較廣泛或持久，但不同荷爾蒙的速度並不完全相同。" },
    { id: "BIO_R4_L_S078_SEC_04", title: "器官共同完成調節", content: "例如體溫偏高時，神經中樞可促使汗腺分泌與皮膚血流改變；水分偏低時，神經與荷爾蒙訊號可影響口渴及腎臟保水。恆定來自多器官協調。" },
  ],
  [
    { id: "BIO_R4_L_S078_EX_01", prompt: "碰到熱物立刻縮手，主要顯示哪種協調特徵？", steps: ["辨認反應需要快速傳訊", "判斷控制到特定肌肉的路徑"], answer: "神經訊號快速傳到特定肌肉", why: "縮手需在短時間內把感覺資訊傳入並把運動指令送到相關肌肉，神經路徑能提供快速且較精確的控制，降低持續受熱傷害。" },
    { id: "BIO_R4_L_S078_EX_02", prompt: "某荷爾蒙進入全身血液，為何不是所有細胞都相同反應？", steps: ["確認訊號雖可隨血到各處", "檢查細胞是否具有相應受器"], answer: "只有具有相應受器的目標細胞能有效回應", why: "荷爾蒙可隨血液廣泛分布，但訊號必須和目標細胞受器配合才能啟動特定反應，因此傳到不等於每個細胞都作出同樣變化。" },
    { id: "BIO_R4_L_S078_EX_03", prompt: "缺水時腎臟保水增加，能否說是荷爾蒙直接形成尿液？", steps: ["區分訊號與效應器功能", "確認腎臟才是實際處理器官"], answer: "不能，荷爾蒙調節腎臟，腎臟才改變水分處理", why: "荷爾蒙是傳遞狀態與調節需求的化學訊號，並不取代腎臟的組織結構；腎臟細胞收到訊號後改變水分回收，才造成尿量變化。" },
  ],
  [
    { belief: "神經訊號就是肌肉收縮本身", whyWrong: "神經負責傳遞指令，肌肉細胞收到訊號後才完成收縮。", correction: "應區分控制訊號與效應器反應，兩者依序合作但不是同一現象。" },
    { belief: "荷爾蒙只在分泌腺附近作用", whyWrong: "荷爾蒙可進入血液到達遠端目標器官，不限於腺體旁。", correction: "作用位置由血液運送與目標細胞受器決定，而不是只看距離。" },
    { belief: "荷爾蒙流到哪裡，所有細胞都會同樣反應", whyWrong: "沒有相應受器的細胞通常不會產生該荷爾蒙的特定反應。", correction: "訊號可廣泛分布，但反應具有目標細胞與受器的選擇性。" },
    { belief: "恆定只靠一個器官獨立完成", whyWrong: "受器、中樞、訊號途徑與效應器需協調，且常涉及多個器官。", correction: "分析調節時應依序找出感受、整合、傳訊與器官反應各環節。" },
  ],
  [
    { prompt: "神經系統在調節中的主要角色是什麼？", answer: "快速傳遞並整合訊息以控制效應器", reason: "感覺資訊進入中樞後，神經指令可沿特定路徑送到肌肉或腺體。" },
    { prompt: "荷爾蒙為何只作用於部分細胞？", answer: "目標細胞具有相應受器", reason: "化學訊號需與受器配合才能啟動反應，隨血液到達不代表一定有效。" },
    { prompt: "缺水調節中腎臟扮演什麼角色？", answer: "接受調節訊號並實際改變水分回收", reason: "神經與荷爾蒙提供指令，腎臟細胞才是調整尿液水量的效應器。" },
  ],
));

questions.push(
  question("BIO_R4_Q_078_01", "BIO_R4_S078", "foundation", "調節流程中，首先偵測體內變化的構造稱為何者？", ["受器", "效應器", "尿液", "糞便"], 0, ["受器能感受溫度或濃度等變化，啟動後續訊息傳遞。", "效應器接收指令後作出反應，並非最先偵測變化的構造。", "尿液是排出物，不是能感受並傳送調節資訊的構造。", "糞便主要是消化道殘餘，沒有作為調節受器的功能。"], ["完整調節由感受開始，受器提供目前狀態的資訊。", "沒有偵測便難以針對偏差調整，因此受器是流程中的必要前端。"]),
  question("BIO_R4_Q_078_02", "BIO_R4_S078", "foundation", "神經訊號相較多數荷爾蒙作用，常具有哪項特徵？", ["只能經血液傳遞", "反應較快速且路徑較明確", "完全沒有目標器官", "永遠維持數年"], 1, ["荷爾蒙主要經血液傳遞，神經訊號則沿神經細胞路徑。", "神經傳訊通常快速，可在特定路徑控制相應效應器。", "神經反應需要肌肉或腺體等目標，不會完全沒有目標器官。", "多數快速神經訊號不會在同一強度下永遠維持數年。"], ["比較重點是典型時間尺度與傳遞路徑，不代表所有情況毫無例外。", "縮手或瞳孔改變等快速反應，常能顯示神經控制的特徵。"]),
  question("BIO_R4_Q_078_03", "BIO_R4_S078", "foundation", "內分泌腺分泌的荷爾蒙主要經何者運到遠端器官？", ["食道", "氣管", "血液", "輸尿管"], 2, ["食道運送食團到胃，不會把荷爾蒙送往全身目標細胞。", "氣管運送空氣，並不是內分泌化學訊號的主要載體。", "荷爾蒙進入血液後，可隨循環到達遠端目標器官。", "輸尿管把尿液送到膀胱，方向與荷爾蒙分布不同。"], ["內分泌的名稱提示分泌物進入體內，血液負責完成遠距運送。", "到達細胞仍不代表一定反應，還要看是否具有相應受器。"]),
  question("BIO_R4_Q_078_04", "BIO_R4_S078", "standard", "下列哪個調節順序最合理？", ["效應器→受器→外界完全不變", "荷爾蒙→糞便→食物", "尿液→中樞→受器", "受器偵測→中樞整合→訊號傳出→效應器反應"], 3, ["受器應先偵測變化，效應器不會在沒有資訊時成為固定起點。", "糞便與食物不是荷爾蒙調節訊息的標準連續路徑。", "尿液是調節結果之一，不能取代最前端受器的偵測。", "從感受到整合、傳訊再到器官反應，符合資訊流向。"], ["依訊息處理流程排序，可避免把結果誤當成偵測變化的原因。", "實際系統可有多層回饋，但基本四環節仍可用來定位受損位置。"]),
  question("BIO_R4_Q_078_05", "BIO_R4_S078", "standard", "荷爾蒙隨血液到達許多細胞，為何只有部分細胞反應？", ["只有目標細胞具有相應受器", "其他細胞完全沒有水", "血液只流過一個器官", "荷爾蒙會變成神經"], 0, ["受器能辨認化學訊號，具有相應受器的細胞才會啟動特定反應。", "細胞普遍含水，水分有無不是荷爾蒙選擇性的合理原因。", "血液循環可到多個器官，並非只流過單一部位。", "荷爾蒙與神經訊號是不同形式，不會因到達細胞便互相轉變。"], ["區分訊號分布與訊號辨識，廣泛到達仍可產生選擇性反應。", "受器種類和數量改變也可能影響細胞對同一荷爾蒙的敏感程度。"]),
  question("BIO_R4_Q_078_06", "BIO_R4_S078", "standard", "碰到熱物立刻縮手，主要依賴哪種快速協調？", ["糞便形成", "神經傳訊與肌肉反應", "尿素排出", "食物吸收"], 1, ["糞便形成耗時且屬排遺，不能產生快速縮手動作。", "感覺與運動神經快速傳訊，肌肉收到指令後收縮。", "尿素排出由腎臟進行，與特定手臂肌肉快速反應不同。", "養分吸收不能在瞬間控制縮手的方向與時間。"], ["快速且指向特定肌肉的反應，最符合神經系統控制。", "神經負責訊號，肌肉才是實際產生動作的效應器，兩者不可混稱。"]),
  question("BIO_R4_Q_078_07", "BIO_R4_S078", "standard", "缺水時荷爾蒙訊號影響腎臟，最合理的分工為何？", ["荷爾蒙直接變成尿液", "腎臟製造荷爾蒙後變成神經", "荷爾蒙傳訊，腎臟改變水分處理", "血液停止運送訊號"], 2, ["荷爾蒙是訊號分子，不會整體直接轉變成尿液。", "器官不會因分泌或接收訊號就轉變為神經組織。", "訊號調節腎細胞活動，腎臟才實際改變尿液水量。", "荷爾蒙需隨血液到達腎臟，血液停止會妨礙而非完成調節。"], ["訊號與執行器官分工，能避免把荷爾蒙說成直接替代器官。", "判讀異常時也要分辨訊號不足與腎臟無法回應兩種不同原因。"]),
  question("BIO_R4_Q_078_08", "BIO_R4_S078", "advanced", "受器無法偵測體溫升高，即使汗腺正常，可能有何結果？", ["汗腺必定持續最大分泌", "體溫一定立即歸零", "肺泡變成受器", "散熱反應可能無法在適當時機啟動"], 3, ["缺少升溫訊息不會保證汗腺持續接受最大分泌指令。", "偵測異常可能使升溫加劇，不會讓核心體溫立即變為零。", "肺泡不會因體溫受器失效就轉變成新的受器組織。", "前端資訊缺失會使中樞難以針對偏差發出正確調節訊號。"], ["效應器構造正常不代表整條控制路徑正常，受器也是必要環節。", "可比較受器訊號與汗腺反應，定位問題在感受端還是執行端。"]),
  question("BIO_R4_Q_078_09", "BIO_R4_S078", "advanced", "某荷爾蒙濃度正常但目標細胞缺少受器，最合理預測為何？", ["目標反應仍可能不足", "所有細胞反應都加倍", "荷爾蒙直接變成氧氣", "血液因此完全消失"], 0, ["訊號存在但無法被有效辨認，目標細胞反應仍可能下降。", "缺少受器不會讓所有細胞對該訊號的反應自動加倍。", "荷爾蒙不會因受器缺失就化學轉變成氧氣分子。", "受器異常不會使全身循環中的血液完全消失。"], ["訊號濃度和細胞反應能力是兩個環節，任一受損都可能影響結果。", "此情境提醒不能只量荷爾蒙濃度，還需檢查目標組織是否能回應。"]),
  question("BIO_R4_Q_078_10", "BIO_R4_S078", "advanced", "要區分反應由神經或荷爾蒙主導，哪組資料最有用？", ["反應器官的收縮幅度", "反應時間、傳遞路徑與是否經血液", "刺激前後受試者的心跳頻率", "量測表格邊框"], 1, ["反應幅度不能指出訊號經神經路徑或隨血液傳遞。", "時間尺度與神經或血液路徑能直接區分兩種傳訊模式。", "心跳可能是共同反應，沒有提供傳遞速度與訊號路徑。", "表格外觀不會改變神經活動或荷爾蒙濃度。"], ["判斷應使用訊號本身的時空證據，而不是器官外觀或資料排版。", "有些調節同時涉及兩者，結果可能顯示快速啟動與較持久維持兩階段。"]),
  question("BIO_R4_Q_078_11", "BIO_R4_S078", "transfer", "自動空調的感測器、控制器與冷氣機，依序類比何者？", ["效應器、受器、中樞", "尿液、腎臟、血液", "受器、中樞、效應器", "肺、糞便、胃"], 2, ["感測器應先對應受器，不能把效應器放在流程起點。", "三者功能是偵測、決策、執行，不類比尿液形成路徑。", "感測器偵測、控制器整合、冷氣機執行，順序相符。", "肺、糞便與胃無法依序對應這套資訊控制功能。"], ["類比以功能與資訊方向為準，不要求機械設備和人體構造外形相同。", "人體還包含神經與荷爾蒙訊號，空調模型只呈現基本回饋架構。"]),
  question("BIO_R4_Q_078_12", "BIO_R4_S078", "transfer", "藥物阻斷汗腺接收神經指令，炎熱時最可能如何？", ["體溫受器完全消失", "荷爾蒙全部變成汗", "腎臟停止所有功能", "中樞可發訊號但汗腺反應下降"], 3, ["藥物作用在汗腺接收端，不表示體溫受器構造完全消失。", "化學訊號不會整體轉變成汗液，汗仍由汗腺細胞分泌。", "汗腺神經阻斷不會直接使腎臟所有功能完全停止。", "控制端可能正常偵測並發令，但效應器無法充分接收而少汗。"], ["依藥物阻斷位置定位，問題在訊號到效應器的連接而非感受或中樞。", "可同步記錄神經活動和汗量，驗證有指令但器官反應不足的推論。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S078", "BIO_R4_S078", "coordination-pathway-table",
  { title: "升溫後的調節訊號", text: "研究者讓三組模型動物核心溫度同樣升高零點六度。甲組各環節正常；乙組阻斷由溫度受器到中樞的訊號；丙組保留受器訊號，但阻斷中樞到汗腺的神經。", note: "表中神經活動與汗量為相對值，起始體溫及環境相同。" },
  { summary: "表格顯示甲有受器訊號、中樞輸出與高汗量；乙前端訊號低；丙有前端與中樞訊號但汗量低。", colorIndependent: true, dataFallback: { columns: ["組別", "受器傳入訊號", "中樞散熱輸出", "汗量"], rows: [["甲", "90", "88", "85"], ["乙", "8", "12", "10"], ["丙", "91", "86", "9"]] } },
  [
    question("BIO_R4_SQ_078_01", "BIO_R4_S078", "standard", "哪組各環節的升溫散熱反應最完整？", ["三組完全相同", "乙組", "丙組", "甲組"], 3, ["三組汗量與神經資料差異很大，不能判為完全相同。", "乙受器傳入與後續輸出都低，前端訊息明顯受阻。", "丙前端訊號高但汗量低，效應器連接並不完整。", "甲的傳入、輸出與汗量都高，顯示整條路徑可運作。"], ["完整反應要同時看感受、控制輸出和效應器結果，甲三者一致。", "只看中樞輸出會漏掉丙的汗腺反應障礙，因此需串連全部欄位。"]),
    question("BIO_R4_SQ_078_02", "BIO_R4_S078", "advanced", "乙組汗量低最合理的原因為何？", ["升溫訊息未有效傳入，使中樞輸出偏低", "汗腺一定不存在", "受器訊號過高", "血液完全停止"], 0, ["傳入值八使中樞缺少升溫資訊，散熱輸出與汗量都低。", "題目只阻斷傳入訊號，沒有說汗腺構造一定不存在。", "乙受器傳入只有八，與過高的敘述方向相反。", "模型仍有各項量測，沒有全身血液完全停止的證據。"], ["由最前端異常沿流程解釋後續下降，比只看到少汗便怪罪汗腺更合理。", "若直接刺激汗腺仍能分泌，可進一步證明效應器本身仍有功能。"]),
    question("BIO_R4_SQ_078_03", "BIO_R4_S078", "transfer", "丙組資料最能定位哪個受損環節？", ["溫度受器無法偵測", "中樞訊號到汗腺或汗腺反應受阻", "中樞無法產生任何輸出", "核心溫度沒有上升"], 1, ["丙受器傳入九十一，顯示偵測升溫的訊號仍高。", "前端與輸出正常但汗量九，問題位於輸出之後的執行環節。", "丙中樞輸出八十六，不能說中樞完全沒有輸出。", "題幹明示三組核心溫度同樣上升，不能否認刺激存在。"], ["定位控制路徑要找第一個和正常組分離的欄位，丙在汗量才明顯下降。", "要再區分神經末端與汗腺本身，可直接刺激汗腺並測其分泌能力。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S079", "BIO_R4_S079",
  ["依題目提供的參考範圍判斷內在狀態是否偏高、偏低或範圍內", "結合重複量測、時間趨勢與調節反應形成有限結論"],
  [
    { id: "BIO_R4_L_S079_SEC_01", title: "先確認變項與單位", content: "讀取生理資料前要確認測量的是體溫、濃度或速率，也要注意單位與時間。數字相同但單位不同不能直接比較，量測時點不同也可能代表不同狀態。" },
    { id: "BIO_R4_L_S079_SEC_02", title: "用提供範圍判讀", content: "題目若提供參考範圍，數值低於下限、位於範圍內或高於上限可分別描述。範圍是判讀工具，不代表每一時刻只能等於單一固定值。" },
    { id: "BIO_R4_L_S079_SEC_03", title: "趨勢比單點更完整", content: "連續資料可顯示偏差是否正在擴大、回復或只是一時波動。單一超界值可能來自真實變化或量測誤差，宜在安全情況下重測並檢查方法。" },
    { id: "BIO_R4_L_S079_SEC_04", title: "資料不能直接替代診斷", content: "生理指標超出題目範圍可描述為偏高或偏低，但不能只靠一筆數值確定病因。還需症狀、其他指標、個人基準與專業評估才能形成高風險結論。" },
  ],
  [
    { id: "BIO_R4_L_S079_EX_01", prompt: "參考範圍36.4至37.4度，量得37.8度應如何描述？", steps: ["確認攝氏度單位相同", "將數值和上限37.4比較"], answer: "高於題目提供的參考範圍", why: "三十七點八高於上限三十七點四，因此可描述本次體溫偏高；但一筆數值不足以判定原因，仍應確認量測方法與後續變化。" },
    { id: "BIO_R4_L_S079_EX_02", prompt: "連續三次讀值為8、20、9，如何處理中間值？", steps: ["比較三次結果的一致性", "檢查中間值是否可能為操作誤差"], answer: "重測並檢查儀器，不應直接挑選或刪除", why: "二十和前後讀值差距很大，可能是真實短暫變化也可能是誤差；記錄原值、檢查方法並重測，比任意刪除或直接當病因更可靠。" },
    { id: "BIO_R4_L_S079_EX_03", prompt: "指標先超界後逐步回到範圍，最保守結論為何？", steps: ["按時間確認偏差方向", "比較最後讀值與參考範圍"], answer: "本次偏差正在回復，但仍需持續觀察", why: "連續數值朝參考範圍移動，支持調節可能正在恢復；然而短期回到範圍不能證明原因已完全消失，也不能推廣到未量測時段。" },
  ],
  [
    { belief: "正常生理值只能等於一個固定數字", whyWrong: "生理值可在一定範圍內波動，且受活動、時間與個體差異影響。", correction: "應使用題目提供的參考範圍與趨勢，不把單一平均值當唯一正常值。" },
    { belief: "一筆超界資料就能確定特定疾病", whyWrong: "超界可由多種原因或量測誤差造成，單點不具有足夠病因證據。", correction: "先描述偏高或偏低，再用重測、症狀與其他資料進一步判斷。" },
    { belief: "不同單位的數字可以直接比大小", whyWrong: "單位代表不同尺度，未換算便比較會造成錯誤結論。", correction: "先統一單位與時間基準，再進行範圍、差值或趨勢比較。" },
    { belief: "看到不符合預期的數字就可以刪除", whyWrong: "異常值可能是真實現象，任意刪除會造成選擇偏差。", correction: "保留原始紀錄、檢查操作並重測，依預先規則判斷是否排除。" },
  ],
  [
    { prompt: "判讀生理數據前先確認哪些資訊？", answer: "變項、單位、時間與參考範圍", reason: "只有同單位且對應同情境的資料，才能和範圍或其他時點公平比較。" },
    { prompt: "單一超界值最適合先如何描述？", answer: "本次數值高於或低於提供範圍", reason: "這是資料直接支持的結論，病因仍需重測與其他證據才能判定。" },
    { prompt: "連續數據的價值為何？", answer: "顯示偏差擴大、持續或回復的趨勢", reason: "時間序列比單一讀值更能呈現調節方向，也有助辨認偶發誤差。" },
  ],
));

questions.push(
  question("BIO_R4_Q_079_01", "BIO_R4_S079", "foundation", "題目給定參考範圍4至7，測得6，應如何判讀？", ["位於參考範圍內", "低於下限", "高於上限", "無法知道任何資訊"], 0, ["六介於四和七之間，因此位於題目提供的參考範圍。", "六大於下限四，不能判定為低於下限。", "六小於上限七，不能判定為高於上限。", "題目已有數值與範圍，可判讀相對位置而非毫無資訊。"], ["範圍包含從下限到上限的數值，六明確落在其中。", "範圍內不表示永遠健康，只表示本次此指標未超出題目界線。"]),
  question("BIO_R4_Q_079_02", "BIO_R4_S079", "foundation", "參考範圍10至15，測得8，最適當描述為何？", ["高於上限", "低於下限", "一定等於平均", "單位可以忽略"], 1, ["八低於十五，不會高於參考上限。", "八小於下限十，應描述為低於提供的參考範圍。", "題目沒有提供平均值，低於範圍也不會等於平均。", "判讀仍需確認單位一致，不能宣稱單位可以忽略。"], ["先將讀值和最近界線比較，八低於十所以判為偏低。", "偏低是資料描述，不應只靠此數字直接指定疾病或原因。"]),
  question("BIO_R4_Q_079_03", "BIO_R4_S079", "foundation", "參考範圍36.4至37.4度，測得38.0度，何者正確？", ["低於範圍", "剛好在範圍內", "高於範圍", "一定是儀器壞掉"], 2, ["三十八高於下限，不可能描述成低於整個範圍。", "三十八大於上限三十七點四，並不在範圍內。", "讀值超過上限，可描述為本次體溫高於參考範圍。", "超界可能是真實或誤差，單筆資料不能確定儀器一定故障。"], ["數值與上限單位相同，可直接比較並判定高於範圍。", "下一步可重測與觀察症狀，但不應在題目證據之外自行確定病因。"]),
  question("BIO_R4_Q_079_04", "BIO_R4_S079", "standard", "比較兩份濃度資料前，哪項最重要？", ["表格顏色相同", "數字字型一致", "受試者姓名長度相同", "確認單位與量測時間可比較"], 3, ["顏色只影響呈現，不能保證濃度尺度一致。", "字型不會改變數值單位或量測時點。", "姓名長度與生理濃度資料沒有直接關係。", "單位與時間不同可能造成表面數字誤導，需先統一。"], ["比較數值前先處理尺度和情境，能避免把不可比資料強行排序。", "若單位可換算，應完成換算並保留原始紀錄，再做後續分析。"]),
  question("BIO_R4_Q_079_05", "BIO_R4_S079", "standard", "連續資料12、10、8，而參考範圍6至9，最合理趨勢為何？", ["由高於範圍逐步回到範圍內", "由低於範圍持續下降", "三次完全相同", "數值逐步升高"], 0, ["十二與十高於上限九，最後八進入範圍，呈逐步回復。", "讀值由十二降到八，不是從低於範圍繼續下降。", "三個數字各不相同，不能說完全相同。", "序列方向是下降而不是逐步升高。"], ["時間順序顯示偏高程度縮小，最後讀值落入提供範圍。", "仍只能說本次趨勢回復，不能保證未來一定持續或病因已完全消失。"]),
  question("BIO_R4_Q_079_06", "BIO_R4_S079", "standard", "單次讀值明顯超界但受試者無不適，最合理下一步為何？", ["直接刪除數值", "檢查方法並重複量測", "立即宣稱特定疾病", "修改參考範圍配合數值"], 1, ["異常值可能是真實，沒有檢查前不應任意刪除。", "重測與檢查儀器可判斷是否為操作誤差或持續變化。", "一筆超界不足以確定特定病因，尤其尚無其他資料。", "參考範圍不能為了符合單一結果而事後任意修改。"], ["保留原始資料並重測，是兼顧真實異常與量測誤差的做法。", "若重測仍超界或出現不適，應依情境尋求適當專業評估。"]),
  question("BIO_R4_Q_079_07", "BIO_R4_S079", "standard", "群體平均值為7，個人讀值為8且仍在參考範圍，何者合理？", ["個人一定異常", "平均值就是唯一正常值", "讀值可在範圍內波動，不必等於平均", "應把8改寫成7"], 2, ["八仍在題目參考範圍，不能只因不同於平均就判異常。", "平均是群體代表值，不是每個人每次都必須等於的唯一數字。", "生理值可有個體與時間變異，範圍內不要求等於平均。", "原始讀值應如實保存，不能為符合平均而任意更改。"], ["區分平均與參考範圍，可以避免把正常變異誤判為異常。", "若個人長期基準不同，還可比較其自身趨勢，而非只依群體平均。"]),
  question("BIO_R4_Q_079_08", "BIO_R4_S079", "advanced", "三次量測為7、19、7，參考範圍6至8，最適當處理為何？", ["只保留19", "直接把19改成7", "宣稱一定瞬間生病又痊癒", "保留三筆並重測、檢查中間量測"], 3, ["只保留超界值會忽略前後一致資料，造成選擇偏差。", "更改原始數值破壞資料，不是處理異常值的正確方法。", "中間值可能是真實或誤差，現有資料不足以確定病程。", "保留原值並查儀器、操作及重測，可釐清差異來源。"], ["異常值不是自動刪除或自動採信，而是需要可追溯的檢查程序。", "若重測仍高且有相應症狀，才有更多理由把它視為真實狀態變化。"]),
  question("BIO_R4_Q_079_09", "BIO_R4_S079", "advanced", "指標超界後，調節反應增強且數值朝範圍移動，最支持何者？", ["負回饋可能正在修正偏差", "調節使偏差繼續擴大", "所有器官已停止", "參考範圍沒有用途"], 0, ["反應增強伴隨數值回到範圍，符合抵消原偏差的調節。", "數值朝範圍移動而非遠離，不能說偏差持續擴大。", "有調節反應與連續數值，並不支持所有器官停止。", "資料正是利用參考範圍判斷回復方向，不能說範圍無用。"], ["要判斷回饋方向需同時看偏差、反應與後續結果，三者在此一致。", "這仍是功能推論，若阻斷該反應後偏差不再回復，可提供更強因果證據。"]),
  question("BIO_R4_Q_079_10", "BIO_R4_S079", "advanced", "要比較運動前後某濃度，哪項設計最可靠？", ["前後使用不同單位", "同一方法在明確時點重複量測", "只記感覺不記數字", "只保留符合預期者"], 1, ["單位不同又不換算會使前後數字無法公平比較。", "一致方法、明確時間與重複測量可降低方法差異與偶然誤差。", "主觀感覺無法取代濃度數值，也不能和參考範圍比較。", "選擇性保留結果會偏向預期，無法呈現完整資料。"], ["控制量測方法讓活動狀態成為主要差異，時間點則建立趨勢順序。", "若活動也改變飲食或飲水，應同步記錄這些可能影響濃度的因素。"]),
  question("BIO_R4_Q_079_11", "BIO_R4_S079", "transfer", "魚缸感測值高於安全範圍後逐步下降，最像何種判讀？", ["數值越高永遠越好", "感測器完全無用", "偏差正朝目標範圍回復", "安全範圍只有單一數字"], 2, ["既然高於安全上限，不能說越高永遠越好。", "感測器提供連續變化，正可用於判斷回復方向。", "超界值逐步下降並接近範圍，符合偏差縮小。", "範圍具有上下界，不會因判讀趨勢就變成單一數字。"], ["類比重點是用範圍和時間序列判斷，而不是魚缸與人體構造相同。", "仍要確認感測器校正，避免把儀器漂移誤認為系統真的回復。"]),
  question("BIO_R4_Q_079_12", "BIO_R4_S079", "transfer", "穿戴裝置顯示一次超界警示，最合理回應為何？", ["立刻自行確定病名", "刪除警示不留紀錄", "認定裝置永遠錯誤", "確認量測條件、重測並結合症狀與專業建議"], 3, ["單一穿戴讀值不足以自行確定特定疾病，可能有量測誤差。", "刪除資料會失去後續比較依據，也無法釐清警示原因。", "一次可疑數值不能證明裝置在所有時候都永遠錯誤。", "查佩戴與環境、重測及考慮症狀，能更安全地評估。"], ["警示適合當作需要確認的線索，而不是自動診斷或自動忽略。", "若數值持續異常或伴隨不適，應依裝置用途尋求適當專業協助。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S079", "BIO_R4_S079", "internal-state-series",
  { title: "運動後指標的回復紀錄", text: "某教學模型的指標參考範圍為70至100單位。學生在運動前、運動後立即及恢復期間以同一儀器量測，每個時點重複兩次取平均。", note: "此為教學模型數值，不作為真實醫療診斷標準。" },
  { summary: "表格顯示指標由運動前範圍內，上升到運動後高於上限，再逐步回到範圍。", colorIndependent: true, dataFallback: { columns: ["時點", "指標（單位）"], rows: [["運動前", "84"], ["運動後立即", "138"], ["恢復10分鐘", "116"], ["恢復20分鐘", "96"]] } },
  [
    question("BIO_R4_SQ_079_01", "BIO_R4_S079", "standard", "依表格，最早位於參考範圍內的時點為何？", ["恢復十分鐘", "運動後立即", "運動前", "恢復二十分鐘"], 2, ["恢復十分鐘一百一十六仍高於上限，尚未進入參考範圍。", "運動後一百三十八高於上限一百，並不在參考範圍內。", "運動前八十四介於七十與一百之間，且是最早的量測時點。", "恢復二十分鐘九十六雖在範圍內，但量測時間晚於運動前。"], ["先依上下限找出範圍內讀值，再比較其時間順序，運動前最早。", "運動前八十四單位早於恢復二十分鐘的九十六單位，兩者雖都在範圍內但時點不同。"]),
    question("BIO_R4_SQ_079_02", "BIO_R4_S079", "advanced", "運動後至恢復二十分鐘呈現何種趨勢？", ["持續遠離參考範圍", "先降到零再升高", "三次完全相同", "由138降到116再到96，逐步回復"], 3, ["數值逐步靠近並進入範圍，不是持續遠離。", "表中沒有零值，也沒有先降為零再上升的紀錄。", "一百三十八、一百一十六與九十六彼此不同。", "時間序列連續下降，最後九十六回到七十至一百之間。"], ["依時間順序而非大小任意排列，可看見偏高狀態逐步縮小。", "資料支持回復趨勢，但不能單靠它確定是哪一器官或訊號造成調節。"]),
    question("BIO_R4_SQ_079_03", "BIO_R4_S079", "transfer", "若恢復十分鐘兩次原始值為115與117，平均116是否合理？", ["合理，兩值相加除以二為116", "不合理，應只留117", "不合理，平均應為232", "無法計算任何平均"], 0, ["一百一十五加一百一十七為二百三十二，除二得一百一十六。", "只留較高值會忽略另一筆資料，不能代表兩次平均。", "二百三十二是兩值總和，未除以量測次數。", "已有兩個明確數值與次數，可以直接計算算術平均。"], ["平均計算可檢查表格處理是否一致，也保留原始值供變異判讀。", "兩次讀值只差二單位，顯示本時點重複量測相對接近。"]),
  ],
));

lectures.push(lecture("BIO_R4_L_S080", "BIO_R4_S080",
  ["說明恆定是生理變項在一定範圍內的動態調節", "由偏差、反向調節與回復資料辨認負回饋，而非完全不變"],
  [
    { id: "BIO_R4_L_S080_SEC_01", title: "恆定允許合理波動", content: "體溫、水分與某些濃度會隨活動、飲食與時間改變。只要變化受調節並多數維持在可接受範圍，就可視為動態恆定，不必每秒固定在同一數字。" },
    { id: "BIO_R4_L_S080_SEC_02", title: "負回饋抵消偏差", content: "變項高於目標範圍時，調節反應通常朝降低方向；變項偏低時則朝升高方向。反應結果抵消原偏差，稱為負回饋。" },
    { id: "BIO_R4_L_S080_SEC_03", title: "調節需要時間", content: "刺激發生後，受器偵測、中樞整合、訊號傳遞與器官反應都需要時間，因此數值可能先偏離再逐步回復，甚至在範圍附近小幅波動。" },
    { id: "BIO_R4_L_S080_SEC_04", title: "恆定能力有界限", content: "極端環境、器官受損或調節訊號失效時，偏差可能超過可調範圍並持續擴大。恆定不表示身體能抵抗任何刺激，也不表示所有人的範圍完全相同。" },
  ],
  [
    { id: "BIO_R4_L_S080_EX_01", prompt: "體溫在36.6至37.1度間變動，是否代表沒有恆定？", steps: ["確認變化是否在合理範圍", "檢查調節是否能限制偏差"], answer: "不代表，範圍內小幅波動可屬動態恆定", why: "恆定的重點是內在狀態被調節在一定範圍，而不是固定單值；活動與晝夜變化可造成小幅波動，只要沒有持續失控便不違反恆定。" },
    { id: "BIO_R4_L_S080_EX_02", prompt: "體溫升高後出汗增加並使體溫下降，屬哪種回饋？", steps: ["辨認原偏差方向為升高", "檢查反應結果是否抵消升高"], answer: "負回饋", why: "原變化是體溫上升，出汗蒸發增加散熱，使體溫朝原範圍下降；反應方向抵消原偏差，符合負回饋而非強化偏差。" },
    { id: "BIO_R4_L_S080_EX_03", prompt: "指標超界後沒有任何反向反應且繼續上升，可推論什麼？", steps: ["檢查是否出現抵消偏差的反應", "判斷數值是否朝範圍回復"], answer: "調節可能失效或刺激超過調節能力", why: "若偏高後仍持續升高，資料不符合有效負回饋正在修正的結果；可能是感受、控制或效應器受損，也可能是外界刺激過強。" },
  ],
  [
    { belief: "恆定代表生理數值永遠完全不變", whyWrong: "生理值會隨時間與活動波動，調節目標通常是一段可接受範圍。", correction: "判斷恆定要看數值是否受控及能否回復，而非要求每次讀值完全相同。" },
    { belief: "任何數值改變都表示調節失敗", whyWrong: "刺激後短暫偏離可能正是調節系統偵測並回應的起點。", correction: "應觀察偏差是否持續擴大，或在反向反應後逐步回到範圍。" },
    { belief: "負回饋會讓原偏差越來越大", whyWrong: "負回饋的效果是抵消原變化，使變項朝目標範圍回復。", correction: "偏高時促進降低、偏低時促進升高，反應方向需相對原偏差判斷。" },
    { belief: "有恆定調節就不會受到極端環境傷害", whyWrong: "調節能力有限，極端刺激可超過散熱、產熱或水鹽調節範圍。", correction: "恆定只在一定條件內維持，超界持續時仍需外在措施或專業協助。" },
  ],
  [
    { prompt: "恆定是否要求數值完全固定？", answer: "否，可在受調節的範圍內波動", reason: "生理活動持續改變，但負回饋可限制偏差並使數值多數維持在範圍。" },
    { prompt: "如何由資料辨認負回饋？", answer: "偏差後出現反向反應並使數值回復", reason: "反應效果若抵消原變化而非強化它，就符合負回饋的方向。" },
    { prompt: "恆定為何可能失敗？", answer: "調節環節受損或刺激超過能力", reason: "受器、訊號或效應器失效，以及極端環境，都可能使偏差持續擴大。" },
  ],
));

questions.push(
  question("BIO_R4_Q_080_01", "BIO_R4_S080", "foundation", "下列哪項最符合生物體的恆定概念？", ["生理值在一定範圍內受調節", "所有數值永遠相同", "身體不受任何環境影響", "器官活動全部停止"], 0, ["恆定是透過調節限制內在變項，使其多數維持在適當範圍。", "生理值會隨活動與時間波動，不需要永遠完全相同。", "環境會影響身體，恆定是回應影響而不是完全不受影響。", "器官需持續活動才能調節，全部停止反而無法維持內在環境。"], ["把恆定理解成範圍與調節，就不會誤認為單一固定數字。", "可接受波動和失控偏差不同，需結合範圍及回復趨勢判斷。"]),
  question("BIO_R4_Q_080_02", "BIO_R4_S080", "foundation", "體溫升高後出汗增加，使體溫下降，屬於何者？", ["排遺", "負回饋", "食物吸收", "完全不變"], 1, ["出汗調節體溫不是排出未消化食物殘餘的排遺。", "出汗造成散熱，反向降低原本上升的體溫，符合負回饋。", "食物吸收讓養分進入體內，不能描述本題反向降溫。", "體溫先升後降且汗量改變，明顯不是完全不變。"], ["判斷回饋要比較原變化和反應效果，兩者方向相反即為重要線索。", "出汗也涉及水分流失，但本題功能焦點是它抵消體溫升高。"]),
  question("BIO_R4_Q_080_03", "BIO_R4_S080", "foundation", "生理值短暫離開平常值後回復，最合理說明為何？", ["一定沒有調節", "所有器官停止", "調節可允許短暫波動", "參考範圍不存在"], 2, ["數值能回復反而可能顯示調節反應有效，不能說一定沒有。", "器官若全部停止便難以產生使數值回復的反應。", "刺激後偏離並逐步回復，符合動態恆定而非固定不動。", "回復到平常狀態不會證明參考範圍不存在。"], ["時間序列比單點更能顯示系統是否把偏差帶回可接受範圍。", "短暫超界仍需看幅度與風險，但不能只因改變便否定恆定。"]),
  question("BIO_R4_Q_080_04", "BIO_R4_S080", "standard", "哪組原偏差與負回饋反應配對正確？", ["體溫升高－產熱再增加", "水分不足－排尿大量增加", "血糖偏低－持續降低血糖", "體溫升高－增加散熱"], 3, ["產熱再增加會強化體溫升高，不是抵消偏差。", "水分不足時大量排尿會使缺水加劇，方向不符負回饋。", "血糖已低再持續降低，會讓偏差擴大而非回復。", "增加散熱可使偏高體溫下降，反應方向抵消原偏差。"], ["負回饋不靠反應名稱判斷，而要看結果是否使變項朝範圍移動。", "同一反應在不同原始狀態下意義可能不同，因此須先讀清偏差方向。"]),
  question("BIO_R4_Q_080_05", "BIO_R4_S080", "standard", "體溫在36.5至37.1度間規律波動，何者最合理？", ["可仍屬範圍內動態恆定", "必定代表所有調節失敗", "體溫計一定故障", "身體完全沒有代謝"], 0, ["小幅且受限的波動可反映活動與時間變化，仍符合動態恆定。", "沒有持續超界資料，不能判定所有調節必然失敗。", "多次規律讀值可能是真實變化，不能直接怪罪儀器。", "體溫存在與波動正顯示身體持續代謝，不是完全沒有代謝。"], ["恆定以適當範圍為目標，而不是強迫每次讀值等於同一數字。", "若波動逐步擴大並超界，才需要進一步檢查調節與量測。"]),
  question("BIO_R4_Q_080_06", "BIO_R4_S080", "standard", "水分不足時尿量下降，對恆定有何意義？", ["使水分流失更多", "減少水分排出以抵消不足", "讓腎臟變成肺", "停止所有血液循環"], 1, ["尿量下降通常會減少而不是增加經尿液流失的水。", "保留較多水分可抵消原本缺水的偏差，符合負回饋方向。", "尿量調節不會使腎臟組織轉變成氣體交換的肺。", "循環仍需把訊號與物質送往腎臟，不會因此全部停止。"], ["先辨認原偏差是水分不足，再看少尿是否朝保存水分方向作用。", "少尿是調節結果之一，不表示完全沒有其他途徑的水分流失。"]),
  question("BIO_R4_Q_080_07", "BIO_R4_S080", "standard", "為何恆定需要受器與效應器共同參與？", ["受器直接完成所有器官反應", "效應器不需任何訊息", "受器偵測偏差，效應器執行修正", "兩者只負責形成糞便"], 2, ["受器提供資訊，不能取代肌肉、腺體或腎臟的實際反應。", "效應器若沒有適當訊號，可能無法在正確時機調整。", "感受與執行分工相接，才能依偏差方向作出修正。", "恆定調節涉及多種變項，不只處理消化道排遺。"], ["控制系統需要知道目前狀態，也需要能改變狀態的器官。", "中樞與傳訊路徑還會連接兩者，任何環節受損都可能影響回復。"]),
  question("BIO_R4_Q_080_08", "BIO_R4_S080", "advanced", "指標偏高後調節反應也使它更高，這最不像何者？", ["偏差擴大", "反應方向相同", "失控風險增加", "有效負回饋"], 3, ["反應讓指標更高，確實會使原偏差進一步擴大。", "原變化與反應結果都朝升高，方向相同。", "持續遠離範圍可能提高超過調節能力的風險。", "有效負回饋應抵消偏高，使指標下降而不是繼續升高。"], ["題目問最不像，應找與資料機制方向相反的概念。", "是否為正回饋仍需完整系統證據，但可以確定它不呈現有效負回饋結果。"]),
  question("BIO_R4_Q_080_09", "BIO_R4_S080", "advanced", "同一刺激後甲回到範圍、乙持續遠離，最合理比較為何？", ["甲的調節較能修正本次偏差", "乙一定比甲健康", "兩者數值必定相同", "甲完全沒有反應"], 0, ["甲朝範圍回復，顯示本次控制路徑較能抵消刺激造成的偏差。", "乙持續遠離範圍，沒有證據支持一定比甲健康。", "兩者趨勢不同，不能宣稱數值必定完全相同。", "甲能回復表示可能有調節反應，不能說完全沒有反應。"], ["以結果是否修正偏差比較功能，不必先知道所有分子細節。", "這只描述本次刺激，不能推廣成甲在所有恆定系統都一定較強。"]),
  question("BIO_R4_Q_080_10", "BIO_R4_S080", "advanced", "如何用資料判斷恆定不是完全不變？", ["只記一個時點", "連續量測顯示小幅波動且偏差後回復", "刪除所有不同數值", "把範圍改成單一值"], 1, ["單一時點沒有時間變化資訊，無法呈現波動與回復。", "時間序列同時顯示變化存在與調節限制，直接支持動態概念。", "刪除不同值會製造假象，不能作為科學證據。", "事後把範圍改成單值只是改定義，沒有測到真實調節。"], ["動態恆定需要時間資料，既看見偏離，也看見反向修正。", "量測誤差仍須評估，但規律且可重複的波動不應被任意刪除。"]),
  question("BIO_R4_Q_080_11", "BIO_R4_S080", "transfer", "恆溫器讓室溫在設定值附近上下小幅變化，最像何者？", ["完全沒有控制", "數值必須固定到無限小數", "生理變項在範圍附近動態調節", "所有刺激都無法影響系統"], 2, ["室溫能在偏差後回復，顯示控制器仍有作用。", "感測與設備啟停需要時間，不必固定到無限精確。", "設定值附近波動並被修正，功能上類似動態恆定。", "開門或外溫仍會影響室溫，控制只是限制影響而非消除刺激。"], ["模型可呈現範圍、延遲與負回饋，不要求室溫永遠完全不動。", "人體調節比恆溫器更複雜，類比不能取代器官與訊號的實際證據。"]),
  question("BIO_R4_Q_080_12", "BIO_R4_S080", "transfer", "極端熱浪中持續出汗但體溫仍升高，最合理解釋為何？", ["出汗一定沒有發生", "負回饋會製造熱浪", "恆定代表不需離開環境", "刺激超過散熱能力，調節不足以抵消偏差"], 3, ["題幹明示持續出汗，不能否認調節反應存在。", "熱浪來自環境，負回饋是身體回應而不是製造熱浪。", "恆定能力有限，危險環境仍需外在降溫與離開暴露。", "散熱雖啟動但小於熱負荷，核心溫度仍可能持續上升。"], ["有調節反應不等於調節一定成功，還要比較反應能力與刺激強度。", "這種持續升溫可能有熱傷害風險，不能以仍在出汗作為安全保證。"]),
);

stimuli.push(stimulus("BIO_R4_ST_S080", "BIO_R4_S080", "homeostasis-time-series",
  { title: "升溫刺激後的體溫與散熱反應", text: "教學模型的體溫參考範圍為36.5至37.2度。零分鐘施加短暫升溫刺激，研究者記錄體溫與散熱反應相對值；反應值越高表示出汗與皮膚散熱作用越強。", note: "刺激在十分鐘停止，其後環境恢復原條件。" },
  { summary: "表格顯示體溫先升高超界，散熱反應隨後增強，體溫再逐步回到參考範圍。", colorIndependent: true, dataFallback: { columns: ["時間（分鐘）", "體溫（攝氏度）", "散熱反應相對值"], rows: [["0", "36.8", "20"], ["5", "37.6", "45"], ["10", "38.0", "90"], ["20", "37.3", "72"], ["30", "36.9", "28"]] } },
  [
    question("BIO_R4_SQ_080_01", "BIO_R4_S080", "standard", "依表中體溫紀錄，哪個量測時點的體溫最高？", ["0分鐘", "10分鐘", "20分鐘", "30分鐘"], 1, ["零分鐘三十六點八度，位於範圍內且不是最高。", "十分鐘為三十八度，是表中最高體溫。", "二十分鐘三十七點三度，低於十分鐘的三十八度。", "三十分鐘三十六點九度，已回到範圍內。"], ["直接比較同單位體溫欄，十分鐘出現本次最大偏差。", "散熱反應在此時也最高，顯示系統正在回應而非體溫完全固定。"]),
    question("BIO_R4_SQ_080_02", "BIO_R4_S080", "advanced", "哪項最支持散熱反應屬負回饋？", ["體溫上升時散熱反應下降", "所有數值始終相同", "體溫偏高後散熱增強，隨後體溫下降", "散熱反應使體溫持續升到更高"], 2, ["表中升溫期間散熱值由二十升到九十，並非下降。", "體溫與反應值都隨時間改變，不是始終相同。", "反應增強後體溫由三十八降至三十六點九，抵消原偏差。", "十分鐘後體溫逐步下降，沒有持續升到更高。"], ["負回饋證據需要反應方向和後續結果，不能只看到反應增加。", "此時間順序符合偏高引發散熱，再使體溫朝參考範圍回復。"]),
    question("BIO_R4_SQ_080_03", "BIO_R4_S080", "transfer", "若模型汗腺失效但其他環節正常，最合理預測為何？", ["散熱反應量測一定更高且體溫更快下降", "體溫不受任何影響", "刺激會立刻消失", "中樞可發出指令，但實際散熱不足使回復較慢"], 3, ["汗腺失效會降低實際蒸發散熱，不能預測更快下降。", "效應器受損會影響調節結果，不可能完全沒有影響。", "汗腺狀態不會使外界施加的升溫刺激在瞬間自行消失。", "控制訊號可能存在，但執行不足會使偏高體溫較難回復。"], ["區分控制指令與效應器結果，能定位有訊號但回復失敗的情境。", "若量到中樞輸出高而汗量低，可進一步支持汗腺執行端受損。"]),
  ],
));

export const BIOLOGY_UNIT_SOURCE = { unitId: "BIO_R4_U10", title: "排泄與恆定", lectures, questions, stimuli, assets: [] };
